quests[1051] = { id = 1051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorrels Rache", description = "Trotz meines freien Willens kann ich der Dunklen Fürstin nicht mehr dienen. Ich fühle, dass meine Zeit in Azeroth zu Ende geht. Meine Lebenskraft ist zerschmettert.\n\nDas hat mir Befrager Vishas angetan! Wochenlang quälte er mich! Nahm mir meinen Ehering und gab ihn seiner Frau. Dieses Monster!\n\nRache... Ich will Rache!\n\nDer eingebildete Narr prahlte immer mit seiner ach so kostbaren Frau Nancy, die am Lordameresee lebte. Spürt diese Frau auf, erschlagt sie und bringt meiner Frau Monika in Tarrens Mühle meinen Ehering.\n\nDies ist mein letzter Wille...", sourceObjective = "Bringt Monika Sengutz in Tarrens Mühle den Ehering von Vorrel Sengutz.", sourceObjectiveStatus = "unverified-source-field" }
quests[1052] = { id = 1052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem Scharlachroten Pfad", description = "Wir vom Scharlachroten Kreuzzug erheben Anspruch auf die Festungen zwischen Herdweiler und Tirisfal. Wir sind recht stolz auf unsere Bastionen der Säuberung in ganz Lordaeron.\n\nIhr habt Euch gegen die Untoten in Desolace bewiesen. Doch die wahre Bedrohung durch die Seuche liegt in Lordaeron.\n\nBegebt Euch nach Süderstade in den Östlichen Königreichen. Sucht dort nach einem Kreuzzügler namens Raleigh der Andächtige. Gebt ihm dieses Empfehlungsschreiben, das mein Siegel trägt, dann wird er Euch zu einem ehrwürdigen Ort in unserem Scharlachroten Kloster führen.", sourceObjective = "Bringt Raleigh dem Andächtigen in Süderstade Bruder Antons Empfehlungsschreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[1053] = { id = 1053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Namen des Lichts", description = "Einst diente ich dem Scharlachroten Kreuzzug mit Ehre, Treue und Stolz. Ich hielt das Ziel, das sie verfolgten, für edel: Azeroth von den Untoten befreien.\n\nAls ich jedoch im Kloster in Tirisfal weilte, erkannte ich, dass sie langsam den Bezug zur Wirklichkeit verloren. Jetzt halten sie jeden für verseucht, der nicht das Wams des Kreuzzuges trägt. Unschuldige Männer und Frauen wurden gefoltert, weil sie angeblich verseucht waren. \n\nDer Scharlachrote Kreuzzug muss im Namen des Lichts zerschlagen werden. Ihr, {name}, müsst ihr wahnwitziges Regime beenden.", sourceObjective = "Tötet Hochinquisitorin Weißsträhne, den Scharlachroten Kommandant Mograine, Herod, den Scharlachroten Helden sowie den Hundemeister Loksey und meldet Euch dann wieder bei Raleigh dem Andächtigen in Süderstade.", sourceObjectiveStatus = "unverified-source-field" }
quests[1054] = { id = 1054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Auswahl der Bedrohung", description = "Direkt im Norden Astranaars leben die Furbolgs vom Distelfellstamm. Meine Späher berichten, dass ihre Zahl sich in den letzten Monaten erhöht hat. Sollten es zu viele werden, könnten sie den Mut finden, Astranaar direkt anzugreifen.\n\nTötet so viele von ihnen, wie Ihr könnt, aber bringt mir den Schädel ihres Häuptlings zum Beweis dafür, dass ihr Bemühen im Keim erstickt wurde... vorläufig.\n\nIch bleibe hier in Astranaar und warte auf Kunde von Euch. Elune sei mit Euch.", sourceObjective = "Bringt Raene Wolfsläufer in Astranaar Dal Blutklaues Schädel.", sourceObjectiveStatus = "unverified-source-field" }
quests[1055] = { id = 1055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raenes Säuberung", description = "Die Rute, jetzt wieder heil, liegt in Euren Händen. Shael'dryn wird von Eurem Erfolg hören wollen.", sourceObjective = "Kehrt zu Shael'dryn beim Mondbrunnen zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1056] = { id = 1056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise zum Steinkrallengipfel", description = "Die Waldgeister sagten mir, dass Ihr mutig und zu reisen gewillt seid.\n\nIm Süden, nicht weit vom Mystralsee entfernt, liegt ein Tunnel namens Steinkrallenpfad. Durch diesen Tunnel gelangt Ihr in ein Gebiet, das im Steinkrallengebirge als Scherwindklippe bekannt ist. Dort angelangt reist südwestlich weiter, am Felskesselsee vorbei und dann nach Norden, den steilen Abhang hinauf, bis Ihr den Steinkrallengipfel erreicht.\n\nDort werdet Ihr von Hüter Albagorm erwartet. Tut, was er sagt, {race}.\n\nDie Reise wird gefährlich.", sourceObjective = "Reist zu Bewahrer Albagorm auf dem Steinkrallengipfel.", sourceObjectiveStatus = "unverified-source-field" }
quests[1057] = { id = 1057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückeroberung des Verbrannten Tals", description = "Als Beschützer der Waldgeister könnt Ihr sicher unschwer erraten, warum ich beunruhigt bin.\n\nIhr seid durch diese Berge gereist, um diesen Gipfel zu erreichen. Sicherlich habt Ihr das Zerrbild gesehen, zu dem das Land geworden ist. Gier hat zur Zerstörung dieser heiligen Hügel geführt.\n\nDie gierige motorisierte Armee der Industriellen hat das Verbrannte Tal im Süden in Brand gesteckt. Was noch schlimmer ist, die Blutfurien, die in unser Land eingedrungen sind, lassen uns nicht dorthin, um mit der Neuanpflanzung zu beginnen.\n\nVertreibt diese elenden Harpyien, {name}!", sourceObjective = "Bewahrer Albagorm auf dem Steinkrallengipfel möchte, dass Ihr 7 Harpyien der Blutfurien, 7 Wegelagerinnen der Blutfurien, 7 Töterinnen der Blutfurien und 7 Wildfedern der Blutfurien erschlagt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1058] = { id = 1058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jin'Zils Waldmagie", description = "Ich bin ja so aufgeregt!\n\nDrei kleine Käfige mit drei kleinen Elfen! Aber was tun wir nur mit unseren süßen Baumschützer-Freunden? Na, lassen wir sie doch... wie nennen sie das doch gleich... Waldmagie schmecken!\n\nIch brauche einen ordentlichen Schuss Steinkrallensaft. Dann brauche ich ein paar Mondlichtläuferschnurrhaare von diesen schrecklichen Katzen. Das schreit nach einer Menge Renneraugen – man kann nie genug Augen haben. Oh, und bevor wir es vergessen, die wertvolle Schuppe eines Feendrachen.\n\nSchnell zum Steinkrallengipfel, {name}, damit ich etwas Waldmagie zusammenbrauen kann!", sourceObjective = "Hexendoktor Jin'Zil in Malaka'jin möchte 5 Portionen Steinkrallensaft, 5 Schnurrhaare eines Mondlichtläufers, 30 Renneraugen und die Schuppe eines Feendrachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1059] = { id = 1059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückeroberung des Verbrannten Tals", description = "Die Blutfurien wurden besiegt. Sie werden sich jedoch schon bald wieder neu gruppieren, wenn wir nichts unternehmen.\n\nGanz weit im Süden des Brachlandes liegt ein Land, das als Tausend Nadeln bekannt ist. Wenn Ihr in Tausend Nadeln nach Westen reist bis zum üppigen Waldrand von Feralas, stoßt Ihr auf einen Druiden namens Falfindel Wegeshut.\n\nDieser große und weise Druide kann große Waldgeister herbeirufen, die bei der Rekultivierung des Verbrannten Tals helfen können.\n\nErzählt ihm von unserer Notlage! Sucht ihn sofort auf!", sourceObjective = "Reist zu Falfindel Wegeshut an der Grenze zwischen Tausend Nadeln und Feralas.", sourceObjectiveStatus = "unverified-source-field" }
quests[1060] = { id = 1060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brief an Jin'Zil", description = "Ihr habt mir sehr geholfen, {name}. Ihr seid ein echter Glücksbringer, wie eine Hasenpfote, und ich möchte, dass Ihr Euch das hier einmal anseht.\n\nDie Harpyien stammen nicht aus dem Brachland. Sie kommen aus einem Ort namens Steinkrallengebirge, ganz weit nordwestlich von hier. Dort könnte es möglicherweise gefährlich für Euch sein, aber dieser Brief muss an einen alten Freund von mir überbracht werden, der dort lebt, ein Hexendoktor mit dem Namen Jin'Zil.\n\nEr wird sich freuen zu hören, dass Serena Blutfeder tot ist, und ich glaube, Ihr werdet das Steinkrallengebirge sehr interessant finden.", sourceObjective = "Überbringt Jin'Zil in seiner Höhle im Steinkrallengebirge Darsoks Brief.", sourceObjectiveStatus = "unverified-source-field" }
quests[1061] = { id = 1061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geister des Steinkrallengebirges", description = "Die Geister des Steinkrallengebirges sind verärgert, weil Goblins und ihre Gefolgsleute das Land ausplündern und brandschatzen. Das Land rief um Hilfe, und jene, die auf so etwas achten... haben es gehört.\n\nSeereth Bruchstein, eine aufstrebende Schamanin der Horde, wurde in das Steinkrallengebirge geschickt. Sie berichtet von umfangreichen Rodungen durch die Goblins und bittet um Hilfe.\n\nTrefft Euch im Steinkrallengebirge mit Seereth. Um zu ihr zu gelangen, folgt der Straße westlich aus der Siedlung des Wegekreuzes im Brachland. Sie hat in der Nähe des Hochwipfeltals ein Lager aufgeschlagen.", sourceObjective = "Sprecht mit Seereth Bruchstein an der Grenze zwischen dem Steinkrallengebirge und dem Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[1062] = { id = 1062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblineindringlinge", description = "Die von Goblins geleitete Venture Company ist in das Steinkrallengebirge umgezogen, um dort Bäume zu fällen und ganze Waldflächen zu brandroden. Die Geister dort sind außer sich vor Schmerz und Wut. Wir müssen der Venture Company Einhalt gebieten!\n\nBegebt Euch nach Nordwesten, jenseits des Hochwipfeltals, und zur Scherwindklippe. Ihr werdet dort die Goblins und ihre Gefolgsleute bei der Arbeit vorfinden - zeigt ihnen, dass die Horde eine Ausbeutung des Steinkrallengebirges nicht billigt. Zeigt es ihnen in der Sprache, die sie am besten verstehen...\n\nGewalt.", sourceObjective = "Tötet 15 Holzfäller der Venture Co. und kehrt dann zu Seereth Bruchstein an der Grenze des Steinkrallengebirges und dem Brachland zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1063] = { id = 1063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ältestengreisin", description = "Um die Geister des Steinkrallengebirges wirklich zu beschwichtigen, müssen wir uns an die Taurenältesten wenden.\n\nIch kenne nicht viele ihrer Anführer, aber einen Namen kenne ich: Magatha. Ich habe gehört, dass sie sehr alt sein soll und sehr viel weiß. Wenn jemand die Tauren um geistige Hilfe bitten kann, dann sie.\n\nMagatha lebt in der Taurenhauptstadt Donnerfels auf der Anhöhe der Ältesten - dem Steilhang im Nordosten der Stadt. Sprecht mit Magatha und berichtet ihr von der Not im Steinkrallengebirge.", sourceObjective = "Sprecht in Donnerfels mit Magatha.", sourceObjectiveStatus = "unverified-source-field" }
quests[1064] = { id = 1064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hilfe der Verlassenen", description = "Die Tauren sind mit dem Land verbunden, und es schmerzt mich, von der Not im Steinkrallengebirge zu hören. Ich fürchte jedoch, dass wir zunächst die Krankheit ausmerzen müssen, bevor wir das Land heilen können.\n\nIst es nicht eine glückliche Fügung, dass wir mit den Verlassenen verbündet sind? Sie wissen viel über Krankheiten. Ich glaube, sie werden uns helfen können, was das gegenseitige Vertrauen zwischen unseren Völkern stärken wird.\n\nSprecht mit Apothekerin Zamah. Sie ist eine Gelehrte und Botschafterin der Verlassenen. Ihr findet sie bei den Teichen der Visionen unterhalb der Anhöhe der Geister.", sourceObjective = "Sprecht bei den Teichen der Visionen mit der Apothekerin Zamah.", sourceObjectiveStatus = "unverified-source-field" }
quests[1065] = { id = 1065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise nach Tarrens Mühle", description = "Um die Venture Company aus dem Steinkrallengebirge zu vertreiben, müssen wir extreme Maßnahmen ergreifen. Extrem, aber ohne Blutvergießen.\n\nEiner meiner Kollegen hat vielleicht genau das Werkzeug, das wir benötigen. Er heißt Lydon und wohnt in Tarrens Mühle im Vorgebirge des Hügellands, das im weit entfernten Lordaeron liegt.\n\nUm ins Hügelland zu gelangen, reist mit dem Zeppelin in unsere Hauptstadt, nach Unterstadt. Geht von dort aus nach Norden nach Tirisfal, dann südwestlich nach Silberwald und südlich ins Hügelland.\n\nSucht Lydon auf und gebt ihm diese Notiz. Sie wird ihm alles erklären.", sourceObjective = "Bringt Apotheker Lydon in Tarrens Mühle Zamahs Notiz.", sourceObjectiveStatus = "unverified-source-field" }
quests[1066] = { id = 1066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Blut Unschuldiger", description = "Ich werde ein Toxin herstellen, mit dem wir der Venture Company die Gewalt entziehen und sie schwach und sanftmütig werden lassen. Das sollte das Problem der Horde im Steinkrallengebirge lösen, meint Ihr nicht?\n\nUm das Toxin herzustellen, benötige ich jedoch das Blut Unschuldiger, eine Zutat, an die man nur schwer herankommt.\n\nGlücklicherweise beschäftigt das Syndikat, das ist eine Gruppe menschlicher Briganten in dieser Region, Schattenmagier... und diese Magier beschaffen sich das Blut Unschuldiger für ihre eigenen unappetitlichen Machenschaften.\n\nIhr findet die Schattenmagier des Syndikats in der Burg Durnholde im Südosten.", sourceObjective = "Bringt Apotheker Lydon in Tarrens Mühle 5 Phiolen mit dem Blut Unschuldiger.", sourceObjectiveStatus = "unverified-source-field" }
quests[1067] = { id = 1067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Donnerfels", description = "Hier habt Ihr das Toxin. Wenn Ihr es gegen die Venture Company einsetzt, sollte es positive, vielleicht sogar ansteckende Ergebnisse erzielen. Ich muss sagen, es ist ziemlich aufregend zu sehen, dass mein Werk tatsächlich eingesetzt wird!\n\nBringt es aber erst der Apothekerin Zamah, bevor Ihr es einsetzt. Sie muss eine Anwendungsmethode für das Toxin entwickeln, um einen größtmöglichen Effekt zu erzielen.", sourceObjective = "Bringt Apothekerin Zamah in DonnerfelsLydons Toxin.", sourceObjectiveStatus = "unverified-source-field" }
quests[1068] = { id = 1068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schreddermaschinen", description = "Es gibt eine Verbindung zwischen der spirituellen Magie der Schamanen und der natürlichen Magie der Druiden. Deshalb können die Schamanen auch das Flehen der Geister des Steinkrallengebirges hören. Vieles, das sie flüstern, verstehe ich nicht, aber eine Nachricht, eine Vision, ist eindeutig...\n\nIch hatte die Vision zweier menschenähnlicher Maschinen, die auf der Scherwindklippe nordwestlich des Hochwipfeltals mit ungeheuerlicher Geschwindigkeit Bäume fällten. Diese Metallbestien müssen aufgehalten werden!\n\nIn meiner Vision trugen diese Maschinen seltsame Symbole:\n\nXT:4 und XT:9.", sourceObjective = "Vernichtet die Schredder XT:4 und XT:9 und kehrt dann zu Seereth Bruchstein an der Grenze zwischen dem Steinkrallengebirge und dem Brachland zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1069] = { id = 1069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eier der Kluftmoosspinnen", description = "Omeletts aus Spinneneiern sind der letzte Schrei in Beutebucht! Das Problem ist nur... dass es in Beutebucht keine Eier gibt.\n\nDas riecht nach einer Geschäftsidee!\n\nAn der Scherwindklippe und im Sishircanyon nordwestlich im Steinkrallengebirge, lebt die Kluftmoosspinne. Bringt mir ihre Eier, dann werde ich Euch reichlich entlohnen!\n\nAn der Scherwindklippe sind die Eihaufen unter den noch verbliebenen Bäumen zu finden.\n\nIm Sishircanyon... tja, wenn Ihr einen schwachen Magen habt, solltet Ihr vielleicht nur die Eier an der Scherwindklippe sammeln...", sourceObjective = "Bringt Mebok Mizzyrix in Ratschet 15 Kluftmooseier.", sourceObjectiveStatus = "unverified-source-field" }
quests[1070] = { id = 1070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wache halten im Steinkrallengebirge", description = "Hallo, {name}.\n\nSo wie Ihr ausseht, scheint Ihr voller Reiselust zu sein. Wart Ihr schon mal im Steinkrallengebirge? Es ist ein Land, das von der Venture Company und anderen Feinden der Nachtelfen heimgesucht wird.\n\nErst neulich schickte Schildwache Wolfsläufer meine Freundin Kaela Schattenspeer dorthin, um zu untersuchen, was mit dem Land geschehen ist, aber ich habe seitdem nichts mehr von ihr gehört. Was mir noch mehr Sorgen macht ist, dass die Allianz sie zusammen mit einem Gnomenmagier losgeschickt hat... das deutet definitiv auf Probleme hin.\n\nWürdet Ihr sie suchen und mir dann Bericht erstatten?", sourceObjective = "Sucht Kaela Schattenspeer, die auf der Scherwindklippe im Steinkrallengebirge den Taleingang beobachtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[1071] = { id = 1071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Aufschub des Gnoms", description = "Wisst Ihr, {name}, ich bin Mitglied der Erleuchteten Vereinigung der Arkanologie, Alchemie und Ingenieurwissenschaften, und es ist mein Ziel... nein, meine PFLICHT!, den Nachtelfen zu zeigen, dass eine Mischung aus Magie, Mixturen und Mechanismen dazu beitragen kann, ihren Wald zu retten.\n\nEs ist jedoch ein Kampf gegen Windmühlen, und die Goblins vermehren sich wie die Kaninchen, wie es scheint. Ich hatte sogar nicht mal Zeit, um meine neuesten Erfindungen zu bauen!\n\nIch brauche etwas Zeit, um zu planen und zu organisieren. Dazu brauche ich jedoch Eure Hilfe bei der Eindämmung der Goblins auf der Scherwindklippe im Osten...", sourceObjective = "Tötet 10 Holzfäller der Venture Co. und 10 Roder der der Venture Co. und kehrt dann zu Gaxim Rostknirsch im Steinkrallengebirge zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1072] = { id = 1072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein alter Kollege", description = "Das Gerät, das mir vorschwebt, wird meine am weitesten entwickelte Erfindung sein. Aber wir brauchen einen speziellen Trank, wenn es funktionieren soll. Ich glaube, wir sollten uns gleich an das gute Zeug halten, immerhin könnte das unsere letzte Mission sein.\n\nUnd deshalb brauchen wir einen hochwirksamen Sprengstoff: Nitromirglyceronium.\n\nDie einzige Person, die NG-5 herstellen kann, ist ein alter Freund von mir: Lomac Ritzeldreh. Sucht in Tüftlerstadt nach ihm.\n\nWenn Ihr ihn überreden könnt, uns etwas NG-5 herzustellen, kann ich mich an die Platzierung meiner Geräte machen.", sourceObjective = "Sprecht mit Lomac Ritzeldreh in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[1073] = { id = 1073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stümperhaftigkeit + Chemikalien = Riesenspaß!", description = "Hahaha... Ihr braucht Nitromirglyceronium, um Goblins daran zu hindern, einen Wald zu zerstören?!\n\nEs ist mir egal, ob Ihr Gaxim kennt oder nicht... Ich würde Euch das Zeug allein schon deshalb geben, weil ich sehen will, wie Ihr oder sie in klitzekleine Fetzen explodieren.\n\nEs gibt allerdings ein Problem: Ich hab nichts mehr.\n\nAber ich sag Euch was: Bringt mir die richtigen Tränke, dann stelle ich sofort etwas für Euch her.\n\nDas Mindeste, was Ihr tun könnt, ist, mir ein paar Eurer alchemistischen Fertigkeiten vorzuführen, bevor ich Euch eine Kostprobe meiner größten Erfindung gebe.", sourceObjective = "Bringt Lomac Ritzeldreh in Eisenschmiede 4 schwache Manatränke und 2 Elixiere der schwachen Seelenstärke.", sourceObjectiveStatus = "unverified-source-field" }
quests[1074] = { id = 1074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stümperhaftigkeit + Chemikalien = Riesenspaß!", description = "Bitte sehr, Fremdling. Seid jedoch vorsichtig damit... das Zeug ist hochexplosiv.\n\nFalls Ihr wirklich ein Freund von Gaxim seid, grüßt ihn von mir. Falls nicht, dann viel Spaß beim Selbst-in-die-Luft-jagen.", sourceObjective = "Bringt Gaxim Rostknirsch im Steinkrallengebirge das Nitromirglyceronium.", sourceObjectiveStatus = "unverified-source-field" }
quests[1075] = { id = 1075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Rolle von Mauren", description = "Gut, wenden wir uns jetzt dem Teil meines Planes mit der Fernzündung zu... oh, das hab ich ja noch gar nicht erklärt, stimmt's?\n\nAlso dann mal die Kurzversion: Mit etwas Magie kann ich dafür sorgen, dass der Sprengstoff hochgeht, ohne dass Ihr dabei sein müsst. Ich bastele ein Gerät zusammen, bei dem Ihr nur einen Knopf drücken müsst, damit das NG-5 explodiert, wenn Ihr bereit seid.\n\nIch brauche jedoch einen Zauber von einem Freund in Sturmwind - er heißt Collin Mauren. Ihr findet ihn im dortigen Magierviertel. Er ist ein Mensch, daher solltet Ihr ihn kaum verfehlen können.", sourceObjective = "Sucht Collin Mauren in Sturmwind auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[1076] = { id = 1076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufel in Westfall", description = "Ah, ich glaube, ich hab's. Ein Nachrichtenzauber... Er dürfte den Effekt haben, nach dem er sucht.\n\nIch muss eine Rolle herstellen, auf die der Zauber geprägt ist. Dazu benötige ich die Überreste eines Staubteufels.\n\nWarum geht Ihr nicht nach Westfall und sucht eine dieser elenden Kreaturen, während ich den Rest der Komponenten sammle? Sie sind gefährlich, aber ich bin mir sicher, dass Ihr schon damit klarkommt, zumal Ihr sogar gewillt seid, an einem von Gaxims Experimenten teilzunehmen.\n\nIch werde hier sein, wenn Ihr zurückkommt.", sourceObjective = "Bringt Collin Mauren in Sturmwind die Überreste eines Staubteufels.", sourceObjectiveStatus = "unverified-source-field" }
quests[1077] = { id = 1077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speziallieferung für Gaxim", description = "Bitte sehr, {name}. Das sollte funktionieren.\n\nBitte grüßt Gaxim von mir, wenn Ihr ihn das nächste Mal seht. Ich freue mich schon so darauf, von diesem Abenteuer zu hören, wenn Ihr es überstanden habt.\n\nLebt wohl.", sourceObjective = "Bringt Gaxim Rostknirsch im Steinkrallengebirge die Rolle der Nachrichtenübermittlung.", sourceObjectiveStatus = "unverified-source-field" }
quests[1078] = { id = 1078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche für Mauren", description = "Immer wieder fragen mich Reisende über das Steinkrallengebirge aus. Scheint ein beliebter Ort unter Abenteurern zu sein; spielt keine Rolle, ob man Wyvern oder Elementare sucht, oder ob man Geschäfte mit der Venture Company machen will.\n\nIm Verbrannten Tal tief im Steinkrallengebirge gab es mal eine Basiliskenart, deren Schuppen, wenn man sie zu Staub zermahlte, ein wunderbares Reagenz für einige der Zauber ergab, die ich ersonnen habe.\n\nWenn diese Basilisken noch leben, hätte ich liebend gern ein paar ihrer Schuppen.\n\nLasst Euch Zeit, ich hab keine Eile, aber ich kann Euch gut bezahlen.", sourceObjective = "Bringt Collin Mauren in Sturmwind 8 kristallisierte Schuppen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1079] = { id = 1079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimoperation Alpha", description = "Das ist es, {name}. Seht genau hin. Die Geräte sind fertig und einsatzbereit.\n\nNehmt diese Blätter - sie erklären mehr über die Zünder und den Sprengstoff und wo Ihr ihn platzieren solltet.\n\nDenkt daran, der Erfolg Eurer Mission hängt nicht davon ab, wie viel Schaden Ihr anrichtet. Der Erfolg von Plan Alpha hängt davon ab, dass Ihr die Ingenieurspläne der Venture Company aus dem Sägewerk südlich des Felskesselsees holt.", sourceObjective = "Holt die Ingenieurspläne der Venture Company aus dem Sägewerk auf der Scherwindklippe.", sourceObjectiveStatus = "unverified-source-field" }
quests[1080] = { id = 1080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimoperation Beta", description = "Plan Beta funktioniert genau wie Plan Alpha, {name}.\n\nWir stiften Verwirrung und stehlen dann ihre wertvollen Dokumente.\n\nWir müssen unbedingt diese Dokumente haben... vergesst das nicht.\n\nDie Blätter, die Ihr bereits habt, zeigen Euch, wo Ihr den Sprengstoff platzieren müsst. Kommt mir nur heil und mit diesen Dokumenten zurück...", sourceObjective = "Holt die Dokumente der Venture Company aus der Scherwindmine am Ostende der Scherwindklippe.", sourceObjectiveStatus = "unverified-source-field" }
quests[1081] = { id = 1081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tyrandes Empfang", description = "{name}, ich bin mir sicher, dass Tyrande Wisperwind Euch persönlich für Eure Teilnahme an dieser Mission danken wollen wird.\n\nEs mag auf den ersten Blick zwar nicht so aussehen, aber Ihr habt dazu beigetragen, etwas in Gang zu setzen, das unsere Position im Steinkrallengebirge erheblich stärken wird.\n\nFalls Ihr Euch als unseren Verbündeten im Kampf gegen diese Gräueltaten betrachtet, sucht Tyrande im Tempel des Mondes in Darnassus auf.", sourceObjective = "Sucht Tyrande Wisperwind in Darnassus auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[1082] = { id = 1082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neuigkeiten für Schildwache Thenysil", description = "{name}, Ihr habt Großes geleistet, indem Ihr uns hier geholfen habt.\n\nDie Schildwachen des Eschentals werden Euch reichlich belohnen, wenn Ihr ihnen mitteilt, dass Gaxim und ich noch am Leben sind. Sagt ihnen, dass wir beim Aufhalten der Venture Company und der Heilung des Landes gute Fortschritte machen.\n\nSucht Tara Thenysil in Astranaar auf. Sie wird sich freuen, dass Ihr mit guten Neuigkeiten kommt.", sourceObjective = "Kehrt zu Schildwache Thenysil im Eschental zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1083] = { id = 1083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wütende Geister", description = "Ich weiß nicht genau, was die Venture Company dem Tal angetan hat, aber es ist offensichtlich, dass es von den dortigen Kreaturen überwältigt wurde.\n\nSie steckten den Wald in Brand und benutzten ihre zerstörerischen Erfindungen, um so viel wie möglich des Tals zu zerstören.\n\nIn ihrer Dummheit haben sie jedoch auch noch etwas anderes entfesselt: brennende Geister, Elementare der Flammen, der Steine und der Wut.\n\nDas Land wird Elune nicht mehr lächeln sehen, solange diese Kreaturen frei herumstreifen.\n\nBringt mir ihre glimmenden Überreste, um mir zu zeigen, dass Ihr sie dezimiert habt.", sourceObjective = "Bringt Kaela Schattenspeer im Steinkrallengebirge 8 glimmende Überreste der Feuerelementare des Verbrannten Tals.", sourceObjectiveStatus = "unverified-source-field" }
quests[1084] = { id = 1084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verletzte Urtume", description = "Es scheint mir offensichtlich, dass die Beschützer des Tales - die Treants - irgendetwas damit zu tun hatten, dass die Venture Company zurückgeschlagen wurde. Leider wurden selbst diese einst so großen Wächter jetzt verderbt.\n\nGaxim glaubt, dass ihre Verderbnis irgendwie mit den Waffen zusammenhängt, die die Goblins während ihres Rückzuges benutzten.\n\nIch bat ihn, eine Probe von einem verwundeten Treant zu nehmen und sie zu untersuchen, um herauszufinden, ob das wirklich stimmt.\n\nBringt mir ein paar Späne, damit der Gnom mehr darüber herausfinden kann...", sourceObjective = "Bringt Kaela Schattenspeer im Steinkrallengebirge ein Stück eines zerfressenen Spans.", sourceObjectiveStatus = "unverified-source-field" }
quests[1085] = { id = 1085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wache halten im Steinkrallengebirge", description = "Die Lage hier im Steinkrallengebirge ist offensichtlich düster, wenn Nachtelfen und Gnome zusammenarbeiten.\n\nDie Venture Company hat das Land verwüstet und ich habe einen Großteil meines Leben damit zugebracht, der Zerstörung ein Ende zu setzen.\n\nMan sollte Gaxim nicht vorschnell beurteilen; er versteht die Notwendigkeit, warum wir zusammenarbeiten müssen.\n\nWenn Ihr uns helfen wollt, sprecht zunächst mit Gaxim.\n\nEs tut mir leid, dass ich Euch jetzt noch nicht mit guten Neuigkeiten zu Tara zurückschicken kann. Aber vielleicht schon bald.", sourceObjective = "Sprecht mit Gaxim im Steinkrallengebirge.", sourceObjectiveStatus = "unverified-source-field" }
quests[1086] = { id = 1086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Flugapparathafen", description = "Das Toxin ist bereit. Jetzt muss es nur noch ausgeliefert werden. Ihr, {name}, müsst es ausliefern.\n\nDie Venture Company muss irgendwelche Mittel und Wege haben, Nachrichten und leichte Fracht zwischen ihrem Hauptquartier und dem Betrieb im Steinkrallengebirge hin- und herzuschicken. Es könnte ein kleiner Flugplatz sein - nicht groß genug für einen Zeppelin, aber vielleicht für einen Flugapparat. Ihr müsst die Gebiete, die von der Venture Company kontrolliert werden, durchsuchen und diesen Flugplatz finden, falls er existiert. Solltet Ihr ihn finden, platziert das Toxin dort.\n\nPlatziert es und lauft, was Ihr könnt.", sourceObjective = "Bringt den Toxinvernebler zum Flugplatz der Venture Company und kehrt dann zu Apothekerin Zamah zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1087] = { id = 1087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cenarius' Vermächtnis", description = "Ihr könnt Euch nicht vorstellen, wie groß mein Hass auf dieses elende Land ist. Solche Leute wie Cenarius und die Kaldoreidruiden auf dem Gipfel benutzen ihre lächerlichen Mächte, um den Magiefluss zu stoppen, sogar noch so weit von ihrem lächerlichen Besitz entfernt... ihren geliebten Wäldern.\n\nIch wünschte, ich könnte nach Jaedenar zurückkehren und im Fluss der Magie baden, aber mein Meister erlaubt mir erst dorthin zurückzukehren, wenn meine Arbeit getan ist.\n\nZweifellos liebt Ihr die Nachtelfen und ihre Verbündeten genauso wenig wie ich. Helft mir, dann haben wir vielleicht beide etwas davon.", sourceObjective = "Tötet für Brealyn Feuerhand in Sonnenfels 4 Söhne des Cenarius, 4 Töchter des Cenarius und 4 cenarische Botaniker.", sourceObjectiveStatus = "unverified-source-field" }
quests[1088] = { id = 1088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ordanus", description = "Sie dachten, dass man den Fluss der Magie zum Erliegen bringen könnte. Sie haben sich geirrt. Sie dachten, dass sie Ordanus verstecken könnten, aber ich will seinen Kopf!\n\nDie Magie gewährt mir Durchblick. Ja... da ist er. Ein Scheideweg... auf dem Wipfel eines großen Baumes im Eschental. Ein Name... der Rajenbaum. Einer der ältesten Söhne des Waldgottes. Sie haben ihn aus dem Wipfel geschleust, bevor ich ihn finden konnte, aber ihm läuft langsam die Zeit davon.\n\nBringt ihn mir, dann teile ich ein großes Geschenk mit Euch.", sourceObjective = "Bringt Braelyn Feuerhand in der Nähe von Sonnenfels Ordanus' Kopf.", sourceObjectiveStatus = "unverified-source-field" }
quests[1089] = { id = 1089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Bau", description = "Die Druiden errichteten den Krallenbau auf dem Steinkrallengipfel, in dem sie viele mächtige Gegenstände aufbewahren.\n\nSie haben sich ein komplexes Schema ausgedacht, damit sie nicht in die falschen Hände gelangen.\n\nGlücklicherweise konnte ich einem von ihnen... ein paar Details entlocken.\n\nVersteckt in einer kleinen Laterne am Eingang des Baus werdet Ihr den Torwächterschlüssel finden. Damit könnt Ihr die Behälter öffnen, die über den ganzen Bau verteilt sind. Mit den Gegenständen aus diesen Behältern wiederum könnt Ihr ihren Hort öffnen, der sich in einem der zentralen Bereiche befindet.", sourceObjective = "Begebt Euch zum Bau auf den Steinkrallengipfel. Benutzt den Torwächterschlüssel, um Euch die versteckten Gegenstände der Druiden zu besorgen. Benutzt diese Gegenstände, um den Hort des Krallenbaus zu öffnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1090] = { id = 1090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerenzos Befehle", description = "Wisst Ihr, ich war hier einst die zweitwichtigste Person. Das hat sich alles geändert, als Gerenzo hier übernahm. Hat meinen Boss Ziz Fizziks gefeuert und mich zum Arbeiten nach unten in die Minen geschickt. Ziz sagte mir aber, dass ich hier bleiben und Informationen sammeln solle. Sein neuer Boss wird uns gut bezahlen, wenn wir rausfinden, was Gerenzo plant.\n\nEgal, was ich weiß ist, dass Gerenzo befohlen hat, dass Riesenmengen von diesem gold-grünen Erz abgebaut werden sollen. Ich hol Euch eine Probe, damit Ihr sie Ziz bringen könnt, aber Ihr müsst Euch vor Patrouillen hüten, während ich es hole.", sourceObjective = "Nehmt das rätselhafte Erz, nachdem Piznik es fertig abgebaut hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[1091] = { id = 1091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaelas Update", description = "{name}, bringt Kaela diese Briefe. Ich bin mir sicher, dass sie das interessiert. Oder zumindest die Schildwachen.\n\nErzählt Ihr unbedingt, wie erfolgreich wir waren und dass wir es ohne ein bisschen Magie nie geschafft hätten.", sourceObjective = "Bringt Kaela Schattenspeer im Steinkrallengebirge die Dokumente der Venture Company.", sourceObjectiveStatus = "unverified-source-field" }
quests[1092] = { id = 1092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerenzos Befehle", description = "Ich glaube, ich sollte auch langsam darüber nachdenken, hier zu verschwinden. Es wird nicht lange dauern, bis die da oben erfahren, was hier gelaufen ist, und ich bin sicher, dass die keinen großen Wert darauf legen, mich wiederzusehen.\n\nIch schleich mich raus und treffe mich mit Ziz. Hoffentlich kann er mir einen neuen Job besorgen!\n\nIch werde versuchen, hier ein bisschen Ordnung zu schaffen, aber Ihr solltet die Erzprobe sofort zu Ziz bringen. Er sagte mir, dass er irgendwo an der Westseite der Scherwindklippe sein Lager aufgeschlagen hat. Viel Glück.", sourceObjective = "Bringt Ziz Fizziks im Steinkrallengebirge das unbekannte Erz.", sourceObjectiveStatus = "unverified-source-field" }
quests[1093] = { id = 1093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superschnitter 6000", description = "Schrecklich, was die Venture Company hier getan hat, was? Was haben die sich dabei gedacht? Eine Goblinfirma, die einen Gnom anheuert!\n\nEin Glück für mich, dass Stotterspritter ein Genie erkennt, wenn es vor ihm steht. Hat mich eingestellt, gleich nachdem ich gefeuert wurde!\n\nSagte mir, sie wollten eine riesige Holzfällmaschine bauen, und Sput möchte, dass ich für ihn die Pläne dazu stehle. Leider wird Gerenzo - dieser verdammte Gnom - mich umlegen, sobald er mich sieht... würdet Ihr vielleicht die Pläne für mich stehlen? Ihr solltet sie bei einem ihrer Maschinenführer finden.", sourceObjective = "Besorgt für Ziz Fizziks im Steinkrallengebirge die Blaupausen für den Superschnitter 6000.", sourceObjectiveStatus = "unverified-source-field" }
quests[1094] = { id = 1094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weitere Instruktionen", description = "In diesem Umschlag befinden sich alle Informationen, die ich mir schnappen konnte, bevor sie mich vor die Tür setzten... Interne Dokumente der Venture Company, ein paar Handbücher, technisches Zeugs... Oh, und natürlich die Blaupausen für den Superschnitter 6000.\n\nStotterspritter hat sich bei Ratschet im Brachland niedergelassen. Sollte nicht schwer sein, ihn zu finden. Er ist ein kleiner, grüner Kerl.", sourceObjective = "Bringt Stotterspritter in Ratschet im Brachland den versiegelten Umschlag.", sourceObjectiveStatus = "unverified-source-field" }
quests[1095] = { id = 1095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weitere Instruktionen", description = "Die Tatsache, dass die Venture Company diesen Gnom angestellt hat, hat in Lorenhall für einiges Aufsehen gesorgt. Die Handelsbarone finden es nicht gut, dass Razdunk mit Gerenzo gemeinsame Sache macht.\n\nQuizvox hat mich gebeten, mich um das Problem zu kümmern und ich bin mir sicher, dass einer oder zwei dieser Handelsbarone ihn dazu angewiesen haben. Natürlich hat mir der Direktor das nicht erzählt. Sagen wir einfach, ich hätte so eine Ahnung.\n\nWie dem auch sei, Gerenzo muss entfernt werden und es wäre eine passende Prüfung, das Fizzik erledigen zu lassen.", sourceObjective = "Bringt Ziz Fizziks im Steinkrallengebirge die neuen Befehle.", sourceObjectiveStatus = "unverified-source-field" }
quests[1096] = { id = 1096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerenzo Pfeifzang", description = "Ich habe Gerenzo einmal getroffen, und lasst mich Euch eines sagen, er ist nicht gerade eine Schönheit. Sein Fleisch sieht aus, als würde es faulen. Dazu hat er noch überall an seinem Körper Metallteile und Zeugs angeflanscht und sogar einige seiner Körperteile durch mechanische ersetzt.\n\nNordöstlich von hier, weit oberhalb des Felskesselsees in der Nähe des Wasserrades beaufsichtigt Gerenzo die gesamte Stätte. Ich könnte mich unmöglich bis da hinauf durchkämpfen und schon gar nicht mich mit Gerenzo anlegen...Aber Ihr seht aus, als könntet Ihr es schaffen.\n\nWenn Ihr ihn für mich tötet, soll es Euer Schaden nicht sein!", sourceObjective = "Bringt Ziz Fizziks im Steinkrallengebirge Gerenzo Pfeifzangs mechanischen Arm.", sourceObjectiveStatus = "unverified-source-field" }
quests[1097] = { id = 1097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elmores Aufgabe", description = "In Sturmwind gibt es einen zwergischen Waffenschmied namens Grimand Elmore, der mal angedeutet hat, dass er Hilfe bei einer Lieferung bräuchte. Ich glaube, er möchte ein Paket in seine Heimat im Norden schicken.\n\nIhr habt da ein paar schöne kräftige Beine! Falls Ihr also an ein wenig Beinarbeit interessiert seid, sprecht mit Grimand. Wir könnten Euch hier unten brauchen, aber wir müssen auch unsere Bande mit den Zwergen stärken.\n\nIhr findet Grimand Elmore im Waffenladen im Zwergendistrikt von Sturmwind, im nordöstlichen Teil der Stadt.", sourceObjective = "Sprecht mit Grimand Elmore in Sturmwind.", completion = "Ihr seid hier, um mir mit meiner Lieferung zu helfen? Sehr gut!", sourceObjectiveStatus = "unverified-source-field" }
quests[1098] = { id = 1098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todespirscher in Burg Schattenfang", description = "Als Vorbereitung auf einen Überfall auf Schattenfang wurden zwei Todespirscher in die Burg geschickt, um Informationen zu sammeln. Das war vor mehreren Tagen und sie sind noch nicht wieder zurück, aber wir brauchen ihren Bericht, wenn wir auf einen erfolgreichen Angriff hoffen wollen!\n\nDas ist Eure Aufgabe, {name}. Geht zu Burg Schattenfang im Süden und sucht die Todespirscher Adamant und Vincent. Findet sie und helft ihnen, falls es erforderlich ist.\n\nDiese Mission ist nicht nur gefährlich, sondern auch lebenswichtig, {name}. Versagt bitte nicht.", sourceObjective = "Sucht die Todespirscher Adamant und Vincent.", sourceObjectiveStatus = "unverified-source-field" }
quests[1099] = { id = 1099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Goblins haben gewonnen!" }
quests[1100] = { id = 1100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einbraues Tagebuch", description = "Ihr öffnet langsam das verwitterte Tagebuch des Henrig Einbraue...", sourceObjective = "Lest Henrig Einbraues Tagebuch.", sourceObjectiveStatus = "unverified-source-field" }
quests[1101] = { id = 1101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Greisin des Krals", description = "Armer Heralath! Und dieser Zwerg... Einbraue. Was war er doch für eine mutige Seele.\n\nSo viel Heldenmut darf nicht umsonst gewesen sein. Diese Greisin... Charlga Klingenflanke... muss aufgehalten werden.\n\nSicher, es wird gefährlich werden, den Kral zu bespitzeln. Wir haben keine Zeit, um Darnassus zu informieren. {name}, stellt eine Gruppe zusammen, um die Greisin zu erschlagen.\n\nBringt mir Klingenflankes Medaillon zum Beweis ihres Ablebens.", sourceObjective = "Bringt Falfindel Wegeshut in Thalanaar Klingenflankes Medaillon.", sourceObjectiveStatus = "unverified-source-field" }
quests[1102] = { id = 1102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein schreckliches Schicksal", description = "Es war edel von unserem Anführer Cairne, unser Volk hier in Donnerfels zu vereinen.\n\nIch kann jenen jedoch nicht vergeben, die uns so leicht aus dem Land unserer Vorfahren vertrieben haben. Jahrhunderte lang lebte mein Volk im Südlichen Brachland. Das Land war uns heilig. Aber wir wurden von zahllosen Feinden vertrieben.\n\nEin schreckliches Schicksal erwartet die Greisin Charlga Klingenflanke, die im Kral der Klingenhauer eine abscheuliche Armee zusammenzieht.\n\nBringt mir Klingenflankes Herz, damit ich in Frieden sterben kann, {name}.", sourceObjective = "Bringt Auld Steinkeil in Donnerfels Klingenflankes Herz.", sourceObjectiveStatus = "unverified-source-field" }
quests[1103] = { id = 1103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "Seid gegrüßt, <Bruda/Schwesta>! Seid auch Ihr gekommen, um das Wasser hier zu läutern und Islen Euer Wissen zu beweisen?\n\nIch habe den verderbten Wassergeist gerade selbst bezwungen und bin grad dabei, die Armschienen un' verbleibenden Wassertropfen in die Kohlenpfanne zu geben.\n\nWas'n das? Ahhh. Tiev versteht nur zu gut, wenn wat falsch läuft. Tja, Tiev kann Euch echt helfen, wenn Ihr den Wassergeist wieda seh'n wollt.\n\nBringt mir 'in Wassersapta von Islen als Beweis, dass Ihr bereit seid, un' ich bin bereit, meinen Teil beizutrag'n.", sourceObjective = "Bringt Tiev Mordune im Silberwald ein Wassersapta, wenn Ihr nicht mit der schwachen Wassermanifestation gesprochen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1104] = { id = 1104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salziges Gift", description = "Ich habe so viele Pläne für unseren Raketenwagen! So viele! Und ich muss sie alle ausprobieren!!!\n\nIch arbeite gerade an einem neuen Treibstoff; an einem, der wirklich, wirklich, wirklich heiß ist! Die Mixtur stimmt zwar noch nicht ganz, aber ich glaube, ich weiß, was noch fehlt...\n\nDie Skorpide, die die Schimmernde Ebene durchwandern, haben ein Gift mit Unmengen Salz darin. Es ist einzigartig! Und es ist genau das, was ich brauche!\n\nBringt mir das Gift und vertraut mir: unser Wagen wird fliegen!", sourceObjective = "Bringt Fizzel Kupferbolz in der Schimmernden Ebene 6 Einheiten salziges Skorpidgift.", sourceObjectiveStatus = "unverified-source-field" }
quests[1105] = { id = 1105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gehärtete Schalen", description = "Mein Bruder arbeitet an einem neuen Treibstoff für seinen Raketenwagen. Er ist brillant, ehrlich. So brillant, dass... Ich glaube, der neue Treibstoff, den er da entwickelt, ist stark genug, um sich durch das Chassis des Wagens zu fressen!\n\nIch würde gern die Treibstofftanks verstärken, bevor das passiert.\n\nDie Schildkröten draußen auf der Ebene haben sehr starke Panzer. Ich möchte daraus neue Tanks für unseren Raketenwagen bauen. Tanks, die den neuen Treibstoff meines Bruders aushalten.\n\nIhr seht mir verantwortungsbewusst genug aus. Holt Ihr mir solche Panzer?", sourceObjective = "Bringt Wizzel Kupferbolz in der Schimmernden Ebene 9 gehärtete Schildkrötenpanzer.", sourceObjectiveStatus = "unverified-source-field" }
quests[1106] = { id = 1106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Martek der Verbannte", description = "Ich entwickle einen neuen Motor, mit dem der Wagen so schnell wie der Wind wird! Schnell genug, um zu fliegen, ich weiß es! Ich muss nur ein paar Kolben herstellen, die sehr, sehr große Belastungen aushalten. All meine bisherigen Versuche sind fehlgeschlagen, weil ich die Kolben einfach nicht robust genug herstellen kann!\n\nAber es gibt jemanden, der wissen könnte, wie es geht.\n\nSein Name ist Martek der Verbannte. Er ist ein großartiger Schmied und weiß mehr über Metall als alle anderen. Bringt ihm diesen Brief, ich weiß, dass er helfen kann!\n\nAber er lebt weit, weit weg - in Azeroth, im Ödland, in einem Lager, zusammen mit einem Goblin!\n\nSucht ihn!", sourceObjective = "Bringt Martek dem Verbannten im Ödland Fizzel Kupferbolz' Brief.", sourceObjectiveStatus = "unverified-source-field" }
quests[1107] = { id = 1107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verkrustete Schwanzflossen", description = "Unser Raketenwagen ist das schnellste, was es auf der Ebene gibt! So schnell, dass... ich fürchte, die Reibung reißt ihn auseinander!\n\nUm das zu verhindern, muss ich einen Stoff entwickeln, der die beweglichen Teile des Wagens überzieht. Er muss hart sein, aber nicht spröde, und er muss resistent gegen Salzkorrosion sein, sonst wird der Wagen, während er sich in der Schimmernden Ebene befindet, zerfressen.\n\nHabt Ihr schon mal vom Finsteren Riff gehört, {name}? Es liegt vor der Küste des Schlingendorntals. Dort leben Salzschuppenmurlocs, deren Schwanzflossen unabdingbare Zutaten zu meinem Stoff sind.", sourceObjective = "Bringt Wizzel Kupferbolz in der Schimmernden Ebene 10 verkrustete Schwanzflossen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1108] = { id = 1108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Indurium", description = "Ich bin nicht hier draußen, weil ich mich vor Leuten verstecken will. Das Ödland ist reich an Metall, {name}, wenn man den Mut hat, es sich zu holen.\n\nDas Metall heißt Indurium, und wie das Schicksal so spielt, soll es angeblich hohen Widerstand gegen Hitze und Belastung bieten. Das könnte genau das Richtige für Zischels Wagen sein.\n\nAber wir sollten sichergehen. Bringt mir eine Indurium-Probe, dann kann ich seine Eigenschaften testen.\n\nEchtes Induriumerz liegt tief drinnen in Uldaman, aber die Steingrufttroggs des Ödlands tragen manchmal Späne davon mit sich herum. Bringt mir diese Späne.", sourceObjective = "Bringt Martek dem Verbannten im Ödland 10 Induriumspäne.", sourceObjectiveStatus = "unverified-source-field" }
quests[1109] = { id = 1109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Go, Go, Guano!", description = "Wie Ihr seht, {name}, befassen wir uns mit einigen sehr... interessanten Experimenten in der Königlichen Apothekervereinigung.\n\nAls Meister hier ist es meine Aufgabe, die anspruchsvollsten unserer alchemistischen Versuche zu überwachen. So viel Arbeit und nur so wenig Zeit!\n\nIhr seht weit gereist aus, {class}. Vielleicht könnt Ihr mir helfen.\n\nIch brauche eine rare Substanz. Es ist dieses widerliche Zeug, das von einer raren Fledermausart stammt, die man nur in einem Dreckloch namens Kral der Klingenhauer findet. Bringt mir den Guano der Kralfledermäuse, damit wir mit unserer Arbeit beginnen können...", sourceObjective = "Bringt dem Apothekermeister Faranell in Unterstadt 1 Häufchen Kralguano.", sourceObjectiveStatus = "unverified-source-field" }
quests[1110] = { id = 1110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raketenwagenteile", description = "Hi-hi, bei den vielen Rennen, die hier stattfinden, ist es nicht verwunderlich, wenn dabei ein paar Unglücksfälle passieren. Wenn man sich in der Schimmernden Ebene umschaut, sieht man ständig Spuren vergangener Unfälle - überall liegen Teile von Raketenwagen herum.\n\nUnd diese Teile bedeuten für die Gnome und Goblins bares Geld. Sie suchen ständig nach weiteren neumodischen Apparaten, um sie an ihre Autos anzubauen.\n\nAlso zieht los und bringt mir die Teile. Bringt mir einen Haufen und ich werde Euch gut bezahlen.", sourceObjective = "Bringt 30 Raketenwagenteile zu Kravel Kohlebart in der Schimmernden Ebene.", sourceObjectiveStatus = "unverified-source-field" }
quests[1111] = { id = 1111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Werftmeister Flunkerblick", description = "Mein Job ist es, den Leuten zu beschaffen, was sie möchten, und diese Gnome da drüben möchten Teile bestellen. Ihre Teile wurden vor einer Woche nach Ratschet geschickt, aber es war mir nicht möglich, dorthin zu reisen.\n\nAlso, seid Ihr bereit, mir die Kleinarbeit abzunehmen? Geht nach Ratschet und gebt diese Teilebestellung an Werftmeister Flunkerblick - er wird wahrscheinlich bei den Docks sein.\n\nWenn Ihr das macht, habe ich weitere Aufträge für Euch.\n\nAufträge, bei denen eine Menge Profit rausspringen kann...", sourceObjective = "Bringt Kravels Teilebestellung zu Werftmeister Flunkerblick nach Ratschet im Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[1112] = { id = 1112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teile für Kravel", description = "Hier ist Kravels Paket, {name}. Und wenn Ihr es zustellt, sagt ihm bitte... wenn er weitere spezielle Lieferungen möchte, dann muss er bezahlen!", sourceObjective = "Bringt Kravels Teile zu Kravel Kohlebart. Zu finden ist er in der Schimmernden Ebene in Tausend Nadeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[1113] = { id = 1113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herzen des Eifers", description = "Warum ich eine rare Art von Guano benötige, fragt Ihr Euch? Also bei diesem Experiment möchte ich wissen, wie zwei diametral entgegengesetzte chemische Substanzen aufeinander wirken, besonders wenn beide mit einem höchst toxischen Agens kombiniert werden, um die...garstigsten Resultate zu erzielen.\n\nIn der Nordostspitze von Tirisfal liegt das Scharlachrote Kloster. Innerhalb und außerhalb seiner Hallen versammeln sich die wahnsinnigen Jünger des Scharlachroten Kreuzzuges. Es ist völlig egal, wen Ihr tötet, jeder einzelne ist möglicherweise im Besitz des von mir gesuchten Herzens.", sourceObjective = "Apothekermeister Faranell in Unterstadt möchte 20 Herzen des Eifers.", sourceObjectiveStatus = "unverified-source-field" }
quests[1114] = { id = 1114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung für die Gnome", description = "Jetzt, wo ich habe, was ich brauche, gebt diese Teile Fizzel Kupferbolz. Er wartet schon lange darauf - ich bin sicher, das kleine Teil, das ich behalten habe, wird er nicht vermissen...\n\nUnd ich würde ihn auch nicht darauf hinweisen. Es war klein und wertlos.\n\nGlaubt mir.", sourceObjective = "Bringt die empfindlichen Autoteile zu Fizzel Kupferbolz.", sourceObjectiveStatus = "unverified-source-field" }
quests[1115] = { id = 1115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gerüchteverbreiter", description = "Jetzt, da wir diesen Dienst für die Gnome geleistet haben, wird es Zeit, den Goblins einen Gefallen zu tun! \n\nIch habe gehört, dass der Goblinrennfahrer Nazz Kesseldampf diesen Namen nicht immer getragen hat. Ich frage mich, weshalb er ihn änderte. Ob es wohl ein Geheimnis ist und... wie viel ihm dieses Geheimnis wert ist.\n\nWenn jemand die Wahrheit kennt, dann Krazek aus Beutebucht an der Südspitze des Schlingendorntals. Sprecht mit Krazek und fragt ihn nach unserem Goblinrennfahrer.\n\nWenn Ihr nützliche Informationen aus ihm herausbekommt, springt vielleicht Profit für uns raus.", sourceObjective = "Sprecht mit Krazek in Beutebucht im Schlingendorntal.", sourceObjectiveStatus = "unverified-source-field" }
quests[1116] = { id = 1116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traumstaub im Sumpf", description = "Es ist ein großer Gefallen, diese Informationen über Nazz zu beschaffen, {name}. Ja, ein großer Gefallen. Aber Ihr habt den weiten Weg von der Schimmernden Ebene auf Euch genommen... seid Ihr bereit, noch etwas weiter zu reisen?\n\nIhr könntet doch etwas für mich besorgen, während ich Kontakt mit meinen Informanten aufnehme, hm?\n\nHmm... was könnte es denn sein? Wie wäre es mit Traumstaub von den Großdrachenwelpen und Wyrmkin aus den Sümpfen des Elends? Ja, ich hätte gern etwas Traumstaub für meinen Schnupftabakbeutel!\n\nBringt ihn mir, {name}, und ich gebe Euch die gewünschten Informationen.", sourceObjective = "Bringt 10 Körnchen Traumstaub zu Krazek in Beutebucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[1117] = { id = 1117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerüchte für Kravel", description = "Ich musste einige Gefälligkeiten erweisen, eine rare Flasche Elfenwein herschenken und mir selbst einiges zusammenreimen! Aber ich habe die Informationen, die Ihr sucht.\n\nHier, ich habe einen Brief mit einigen sehr interessanten Infos über Euren Freund Nazz Kesseldampf verfasst. Macht damit, was Ihr wollt - für mich wäre es zu gefährlich, ihn zu benutzen.\n\nSagt nur keinem, woher Ihr das habt!", sourceObjective = "Bringt die Goblingerüchte zu Kravel Kohlebart. Zu finden ist er in der Schimmernden Ebene in Tausend Nadeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[1118] = { id = 1118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück nach Beutebucht", description = "{name}, Ihr seid <ein/eine:c> {class}, <dem/der:c> ich trauen kann. Ihr werdet den Auftrag erledigen und die Klappe halten.\n\nIch habe einen neuen Plan geschmiedet. Er ist riskant, aber wenn er funktioniert, könnten wir beide gut absahnen! Und ich glaube, Ihr seid der Richtige, um das durchzuziehen.\n\nAls Erstes müsst Ihr nach Beutebucht zurückkehren. Nun, ich bitte um Verzeihung, {name}. Ich weiß, meine letzte Aufgabe führte Euch dorthin. Aber sprecht diesmal mit Crank Zischelbub.\n\nGebt ihm diesen Brief. Und wenn er um Unterstützung bittet, dann tut, was Ihr könnt, um ihm zu helfen. Es wird sich lohnen.", sourceObjective = "Bringt Kravels Plan zu Crank Zischelbub nach Beutebucht im Schlingendorntal.", sourceObjectiveStatus = "unverified-source-field" }
quests[1119] = { id = 1119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zanzils Mixtur und Fools Starkbier", description = "Ich habe herausgefunden, wie man aus Zanzils Mixtur mit Starkbier ein mächtiges Getränk macht. Fools Starkbier. Und ich glaube, genau das braucht Kravel. Probiert es einfach mal aus und lasst mich wissen, wie es wirkt.\n\nUnd behaltet das Zeug nicht zu lange unbenutzt, {name}. Zanzils Mixtur hat eine seltsame Wirkung auf die Hefe des Starkbiers und regt sie heftig an. Sie bleibt nicht ewig frisch.", sourceObjective = "Bringt Fools Starkbier zu Kravel zurück. Zu finden ist er in der Schimmernden Ebene in Tausend Nadeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[1120] = { id = 1120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gnome betrunken machen", description = "Wir müssen Fools Starkbier an einem aus der Boxencrew ausprobieren. Wenn Ihr es an den Gnomen erproben wollt, hier - nehmt das Starkbier und gebt es dem Gnomenboxenboss.\n\nUnd wartet nicht zu lange. Das Starkbier wird mit der Zeit schlecht.", sourceObjective = "Bringt Fools Starkbier zum Gnomenboxenboss bei der Illusionenrennbahn in Tausend Nadeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[1121] = { id = 1121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Goblins betrunken machen", description = "Wir müssen Fools Starkbier an einem aus der Boxencrew ausprobieren. Wenn Ihr es an den Goblins erproben wollt, hier - nehmt das Starkbier und gebt es dem Goblinboxenboss.\n\nUnd wartet nicht zu lange. Das Starkbier wird mit der Zeit schlecht.", sourceObjective = "Bringt Fools Starkbier zum Goblinboxenboss bei der Illusionenrennbahn in Tausend Nadeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[1122] = { id = 1122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldet Euch bei Zischelbub", description = "Fools Starkbier hat astrein gewirkt! Ich habe beim nächsten Rennen gesetzt... hoffen wir, das Team, das Ihr betrunken gemacht habt, hat sein Auto nummeriert!\n\nBleibt nur noch eine Aufgabe für Euch - bringt diese Notiz zu Crank Zischelbub in Beutebucht. Er wird von dem erfolgreichen Test wissen wollen.\n\nHoffentlich bekommen wir mehr von Fools Starkbier für künftige Rennen!", sourceObjective = "Bringt den Bericht über Fools Starkbier zu Crank Zischelbub nach Beutebucht im Schlingendorntal.", sourceObjectiveStatus = "unverified-source-field" }
quests[1123] = { id = 1123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rabine Saturna", description = "Für diese Aufgabe sucht Majordomus Rabine Saturna für Bewahrer Remulos auf der Mondlichtung Unterstützung bei der Erforschung des riesigen Ödlands weit im Westen von Tanaris und Un'Goro. Er lebt in Nachthafen, dem Hauptort der Mondlichtung.\n\nVorher möchte ich Euch jedoch noch von der Wichtigkeit Eurer Anwesenheit in Kenntnis setzen. Es gibt zunehmend Spannungen zwischen den Nachtelfen von Darnassus und dem Zirkel des Cenarius bei der Mondlichtung. Lasst Euch nicht von völkischer Engstirnigkeit beirren und verlasst Euch auf die Weisheit Eurer Vorfahren, wenn Ihr dort mit dem Zirkel zu tun habt, {name}. Viel Glück.", sourceObjective = "Sprecht mit Rabine Saturna im Dorf Nachthafen auf der Mondlichtung. Die Mondlichtung liegt zwischen dem Teufelswald und Winterquell, und Ihr erreicht es über den Pfad, der aus der Holzschlundfeste herausführt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1124] = { id = 1124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einöde", description = "Westlich des Kraters von Un'Goro entlang des nordwestlichen Grats liegt ein raues Ödland - Silithus. Nur wenige wissen, dass sich hier vor Urzeiten ein Krieg zwischen den Nachtelfen und einer bösartigen, außerirdischen Macht abgespielt hat. Das Böse wurde versiegelt, aber jetzt befürchten wir, dass Kräfte am Werk sind, um diesen... unaussprechlichen Horror wieder zu entfesseln.\n\nSprecht mit Layo Sternenschlag, einem unserer Agenten in Silithus. Sucht nach ihm in Heldenwacht, der letzten Ruhestätte der Gefallenen des Ödlands. Gebt ihm diesen Brief, damit erwerbt Ihr sein Vertrauen.", sourceObjective = "Sprecht in der Nähe des Friedhofs Heldenwacht in Silithus mit Layo Sternenschlag und zeigt ihm Rabines Brief.", sourceObjectiveStatus = "unverified-source-field" }
quests[1125] = { id = 1125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geister vom Südwindposten", description = "Südwestlich von uns liegt ein tragischer Schauplatz – die Ruinen des Südwindpostens. Dort sollten wir mit unserer Arbeit beginnen, {name}.\n\nNach allem, was wir wissen, war dieses Dorf einst ein Stützpunkt der Nachtelfen für Operationen in Silithus. In der Zwischenzeit wurde es längst von den Silithidenschwärmen überrannt, die die Wüsten durchziehen. Ich vermag mir den Gräuel kaum vorzustellen, als die Zerstörung des Dorfs begann...\n\nDie gequälten Geister gefallener Druiden und Schildwachen wandern ziellos durch die Ruinen. Erforscht diesen Ort und befreit die Seelen dieser unglücklichen Kreaturen, wo immer es erforderlich ist.", sourceObjective = "Befreit die Geister von 8 gequälten Druiden und 8 gequälten Schildwachen beim Südwindposten und kehrt dann zu Layo Sternenschlag auf den Friedhof Heldenwacht in Silithus zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1126] = { id = 1126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarmbau im Turm", description = "Wir müssen uns um den Schwarmbau beim Südwindposten kümmern, und ich glaube, ich weiß auch schon, wie wir an ihn herankommen. Meiner Erfahrung nach reagieren die Schwarmbauten der Silithiden empfindlich auf ihre Umgebung. Das erklärt auch ihre Angriffe, als sie die Todesschreie der Geister hörten.\n\nIm Turm sind die Silithiden am stärksten - dort, wo massenweise Wespen herumschwirren. Besteigt den Turm und scheucht den Schwarmbau auf. Meldet Euch zurück, sobald Ihr etwas erfahren habt, aber seid vorsichtig! Wenn Ihr irgendetwas Hilfreiches entdeckt, bringt es zu mir.", sourceObjective = "Besteigt den Turm beim Südwindposten und findet eine Möglichkeit, den Schwarmbau der Silithiden aufzuscheuchen. Bringt alles Ungewöhnliche, das Ihr dabei entdeckt, zu Layo Sternenschlag auf den Friedhof Heldenwacht in Silithus.", sourceObjectiveStatus = "unverified-source-field" }
quests[1127] = { id = 1127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fools Starkbier", description = "Ihr möchtet also etwas von Fools Starkbier, hm? Denkt Ihr daran, wieder die Rennen zu besuchen...?\n\nGut, bringt mir mehr von Zanzils Mixtur und ich braue noch etwas mehr Starkbier für Euch.", sourceObjective = "Bringt 12 von Zanzils Mixturen zu Crank Zischelbub in Beutebucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[1130] = { id = 1130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Melor schickt Kunde", description = "{name}, Melor Steinhuf hat von Euren Taten gehört und Euch einen Weg geebnet.\n\nWenn Ihr ihn einschlagen möchtet, dann geht nach Donnerfels und sprecht mit Melor. Ihr findet ihn auf der Anhöhe der Jäger.", sourceObjective = "Sprecht mit Melor Steinhuf in Donnerfels.", sourceObjectiveStatus = "unverified-source-field" }
quests[1131] = { id = 1131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stahlbiss", description = "Manchmal jagen wir wegen Essen. Manchmal jagen wir wegen der Ehre. Und manchmal jagen wir, um der Lehren der Erdenmutter teilhaftig zu werden.\n\nDoch die Jagd, auf die ich Euch jetzt schicke, hat damit nichts zu tun. Es geht darum, eine Kreatur zu töten, die nicht unter dem Segen der Erdenmutter steht.\n\nDie Hyäne Stahlbiss streift südlich des Brachlandes durch Tausend Nadeln. Sie ist eine Tyrannin, die andere Hyänen anlockt und Furcht und Blutvergießen unter den friedlicheren Wildtieren verbreitet.\n\nSucht Stahlbiss, {name}. Sucht und besiegt sie.", sourceObjective = "Bringt Stahlbiss' Rippe zu Melor Steinhuf in Donnerfels.", sourceObjectiveStatus = "unverified-source-field" }
quests[1132] = { id = 1132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fiora Langohr", description = "Ach, wieder auf See zu sein! Den Kuss des Windes zu spüren und mich von den Wellen wiegen zu lassen wie vor langer Zeit von meiner gesegneten Mutter!\n\nOh, hätte ich doch nur Euer Glück, {class}, denn ich sehe das Meer in Eurer Zukunft!\n\nMeine Aufgabe ist es, eifrige Seelen nach Kalimdor zu bringen, in das Land der unbegrenzten Möglichkeiten! Wenn Ihr Euer Glück in Übersee machen wollt, dann macht Euch auf zum wunderschönen Hafen Auberdine. Sprecht mit meiner Partnerin, der Elfe Fiora Langohr.\n\nSie wird Euer Abenteuer in Kalimdor beginnen lassen!", sourceObjective = "Sprecht mit Fiora Langohr. Sie befindet sich an den Docks von Auberdine in Dunkelküste.", sourceObjectiveStatus = "unverified-source-field" }
quests[1133] = { id = 1133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise nach Astranaar", description = "{name}, geht nach Astranaar. Ich bin sicher, ein eifriges Mitglied der Allianz kann dort viel Gutes tun. Sprecht mit Shindrell Feuerflink und bietet Eure Dienste an.\n\nAber erwähnt nicht, wer Euch geschickt hat. Shindrell kennt mich nicht...", sourceObjective = "Sprecht mit Shindrell Feuerflink in Astranaar.", sourceObjectiveStatus = "unverified-source-field" }
quests[1134] = { id = 1134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prachtschwingen des Steinkrallengebirges", description = "Wir führen keinen offenen Krieg mit der Horde, aber der Frieden ist brüchig. Ihre Agenten gehen häufig gegen uns vor, aber stets heimlich.\n\nEiner dieser Feldzüge wurde uns durch geheime Informanten in Theramore enthüllt, die behaupten, dass die Orcs Gift der Prachtschwingen beim Mirkfallonsee im Steinkrallengebirge im Süden sammeln. Dann benutzen orcische Auftragsmörder das Gift bei ihren geheimen Feldzügen gegen die Allianz!\n\nWenn das stimmt, dann müssen wir sie aufhalten, {name}. Wir müssen ihnen den Zugang zu dem Gift versperren.", sourceObjective = "Bringt 12 Prachtschwingengiftbeutel zu Shindrell Feuerflink in Astranaar.", sourceObjectiveStatus = "unverified-source-field" }
quests[1135] = { id = 1135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steilhanggift", description = "Wie Ihr sicher wisst, werden Wyvern oft von Orcs als Reittiere gezähmt. Weniger bekannt indessen ist, dass das Gift eines Wyvern in manchen Kreisen höher geschätzt wird als die Bestie selbst. Falls Ihr also keine Angst vor einer kleinen Wyvernjagd habt... habe ich einen Job für Euch.\n\nEs gibt einen Ort im Land Tausend Nadeln, er liegt westlich von hier, welcher als der Steilhang bekannt ist. Die dort lebenden Steilhangwyvern haben ein starkes Gift. Stark und kostbar.", sourceObjective = "Bringt 10 Steilhanggiftbeutel zu Fiora Langohr in Theramore.", sourceObjectiveStatus = "unverified-source-field" }
quests[1136] = { id = 1136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostrachen", description = "{name}, jetzt ist es Zeit, weit entfernte Länder zu bereisen. Ihr seid bereit.\n\nIhr jagt jetzt Frostrachen, einen Yeti im Alteracgebirge. Er ist schwer zu erkennen, da sein weißes Fell mit den Schneefeldern seiner Bergheimat verschmilzt. Man bekommt ihn kaum je zu sehen.\n\nAber ich zeige Euch, wie man eines solchen Geschöpfes habhaft wird. Hier, nehmt diese Rolle. Ich habe darauf vermerkt, wie man Frostrachen anlocken kann.\n\nGeht jetzt, {name}. Eure Reise ist lang und viele Herausforderungen harren Eurer. Erst wenn Ihr mit Frostrachens Mähne zurückkehrt, ist Eure Aufgabe abgeschlossen.", sourceObjective = "Bringt Frostrachens Mähne zu Melor Steinhuf in Donnerfels.", sourceObjectiveStatus = "unverified-source-field" }
quests[1137] = { id = 1137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neuigkeiten für Fizzel", description = "Indurium besitzt einen erstaunlichen Hitzewiderstand! Ich bin sicher, es taugt für Fizzels Kolben. Aber er braucht echtes Indurium, nicht nur die Späne.\n\nDas Erz muss tief in den Minen von Uldaman abgebaut werden, an der Nordgrenze des Ödlands. Das ist die wahre Quelle von Indurium.\n\nBestellt Fizzel Kupferbolz Grüße von mir und sagt ihm, was ich Euch gesagt habe.\n\nAngenehme Reise, {name}. Ich wäre nicht überrascht, wenn wir uns wiedersehen - wenn Fizzel von dem Indurium erfährt, schickt er Euch wahrscheinlich nach Uldaman, um es zu holen!", sourceObjective = "Sprecht mit Fizzel Kupferbolz in der Schimmernden Ebene in Tausend Nadeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[1138] = { id = 1138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meeresfrüchte", description = "Ich liebe Krebse. Krebse sind die Früchte des Meeres! Man kann sie backen, grillen, kochen und braten. Man kann sie in der Pfanne braten, frittieren und kurzbraten. Es gibt Krebssalat, Krebssuppe, Krebseintopf, Pfefferkrebs, Zitronenkrebs, Peitscherwurzelkrebs und Eisenschmiedekrebs à la Surprise. Das...das war's eigentlich.\n\nIch angle hier gerade und daher kann ich mir keine feinen Krebsbrocken besorgen. Man kann sie aus Riffkriechern und verkrusteten Gezeitenkriechern kratzen. Man kann viel mit ihnen anstellen. Man kann sie backen, grillen, kochen...", sourceObjective = "Sammelt 6 feine Krebsbrocken für Gubber Blump in Auberdine.", sourceObjectiveStatus = "unverified-source-field" }
quests[1139] = { id = 1139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verlorene Tafel des Willens", description = "Wir haben den Schattenschmiedeklan ausgebremst, indem wir ihn von der Schwarzfelsspitze abgeschnitten haben, doch Hammerzehs Mission wurde noch nicht erfüllt. Sein Tod darf nicht umsonst gewesen sein. Er träumte davon, die Schrifttafel des Willens zu finden: eine Steintafel, graviert mit Magie durch die Titanen selbst, die helfen, ihren Schöpfungen Leben einzuhauchen und ihnen damit einen eigenen Willen ermöglichen. So jedenfalls heißt es in den Legenden.\n\nDennoch müssen wir die Tafel bergen, ehe der Schattenschmiedeklan sie finden kann.\n\nKehrt nach Uldaman zurück, sucht die Tafel und kommt unverzüglich wieder her.", sourceObjective = "Sucht die Tafel des Willens und bringt sie zu Berater Belgrum in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[1140] = { id = 1140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Turm von Althalaxx", description = "Die Schrift der Orcs ist kaum mehr als das Gekritzel eines Kindes. Viele meines Ordens spotteten, als ich ihre Sprache lernen wollte, aber ich fand es hilfreich, meine Feinde besser zu verstehen.\n\nIlkruds Gekritzel zufolge scheint Athrikus immer noch zwei Seelenedelsteine zu besitzen, und diese werden in der Nachtflucht und Satyrnaar aufbewahrt, Satyrgebiete im nordöstlichen Eschental.\n\nSeid vorsichtig da draußen, {name}, die bluttriefenden Tempel der Satyrn können selbst für abgebrühte Helden wie Euch beängstigend sein.", sourceObjective = "Befreit die Hochgeborenenseelen in der Nachtflucht und Satyrnaar und kehrt zu Delgren dem Läuterer in Maestras Posten zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1141] = { id = 1141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Familie und die Angelrute", description = "Ich liebe das Angeln. Die Familie Blump ist berühmt fürs Angeln. Mein Name ist Gubber Blump; ich angle.\n\nEs gibt eine Fischart, die ich hier in der Gegend gern fange. Sie heißt Dunkelküstenbarsch. Früher fuhr ich mit einem Boot hinaus, um Barsche zu angeln, aber seitdem die gemeinen Murlocs gekommen sind, fahren keine Boote mehr raus. Ich wette, dass sie auch alle Barsche aufgefressen haben.\n\nSagt, wollt Ihr mir helfen, Dunkelküstenbarsche zu fangen? Ich würde Euch eine echte Angelrute der Familie Blump geben, wenn Ihr es tun würdet! Es ist eine wirklich gute Angelrute, um damit Fische zu fangen.", sourceObjective = "Fangt 6 Dunkelküstenbarsche für Gubber Blump in Auberdine.", sourceObjectiveStatus = "unverified-source-field" }
quests[1142] = { id = 1142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sterblichkeit schwindet", description = "Ich habe nicht mehr lange zu leben... so... so... schwach.\n\n... der t-t-tapfere Zwerg Einbraue hat jemanden geschickt, Falfindel zu w-w-warnen...\n\nAber bevor ich... s-s-sterbe...\n\n... meine Frau Treshala... ihr Anhänger des Bundes mit mir... gestohlen... von einem der n-n-niederträchtigen Angreifer...\n\nB-B-Bitte sucht ihn... und bringt ihn Treshala in Darnassus zurück...\n\n... mit der Nachricht meines einsamen... Todes.", sourceObjective = "Sucht und bringt Treshalas Anhänger zu Treshala Bachquell in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[1143] = { id = 1143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Turm von Althalaxx", description = "Verstehe. Also wenn das stimmt, was Ihr sagt, dann ist jetzt die Zeit gekommen, endlich zuzuschlagen. Ich glaube, Athrikus residiert in der Turmspitze. Aber seid vorsichtig, er ist von vielen mächtigen Hexenmeistern umgeben, die tödlicher sind als Eure bisherigen Gegner.", sourceObjective = "Tötet Athrikus Narassin und bringt seinen Kopf zu Balthule Schattenhieb nahe des Turms von Althalaxx.", sourceObjectiveStatus = "unverified-source-field" }
quests[1144] = { id = 1144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willix der Importeur", description = "Endlich ist Hilfe eingetroffen!\n\nIhr habt keine Ahnung, wie lang ich hier gefangen gehalten wurde. Ich kann mich nicht erinnern, wann ich zum letzten Mal draußen war.\n\nWisst Ihr, ich bin Unternehmer. Immer auf die schnelle Mark aus, wie man so sagt. Ich habe Wind davon bekommen, dass Mebok Mizzyrix gut für Blaulaubknolle aus diesem Schweinepferch hier bezahlt. Ich dachte mir, das würde ein leichtes Spiel werden. Wie Ihr sehen könnt, habe ich mich geirrt!\n\nWie auch immer, wenn Ihr so freundlich wärt, mir hier raus zu helfen, soll es Euer Schaden nicht sein.", sourceObjective = "Führt Willix den Importeur aus dem Kral der Klingenhauer hinaus.", sourceObjectiveStatus = "unverified-source-field" }
quests[1145] = { id = 1145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwarm wächst", description = "Viele Reisende, die zum Wegekreuz kamen, halfen mir, Eier vom Feld der Riesen zu sammeln, und viele können Geschichten erzählen, wie tödlich diese Kreaturen sind. Ich habe genug gehört, um diese Insekten als größere Bedrohung einzustufen als meine Meister zuerst dachten.\n\nIch brauche einen Kurier, der nach Orgrimmar reist und sich mit Belgrom Felshammer trifft. Das dürfte keine Kleinigkeit werden und es sollte nur jemand gehen, der die Aufgabe ernst nimmt.\n\nBelgrom ist für gewöhnlich vor der Halle der Kriegerhelden zu finden.", sourceObjective = "Stellt Korrans versiegelte NotizBelgrom Felshammer in Orgrimmar zu.", sourceObjectiveStatus = "unverified-source-field" }
quests[1146] = { id = 1146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwarm wächst", description = "Korran ist also zu einer ähnlichen Schlussfolgerung hinsichtlich dieser Insekten gekommen - sie scheinen doch eine größere Bedrohung zu sein, als wir dachten.\n\nVor ein paar Tagen kehrte ein Jäger halbtot aus Tausend Nadeln zurück. Er gehörte zu einem Stoßtrupp, der geschickt wurde, um ein Ausgrabungsteam der Zwerge von der Schimmernden Ebene zu verjagen. Während des Angriffs kamen noch mehr von diesen Insekten aus einer Höhle an der Grabungsstätte und hätten die Gruppe fast getötet.\n\nIhr Anführer war Moktar Krin und sie suchten Zuflucht an der Grenze der Schimmernden Ebene. Bringt ihm diese Notiz.", sourceObjective = "Stellt Belgroms versiegelte Notiz Moktar Krin in Tausend Nadeln zu.", sourceObjectiveStatus = "unverified-source-field" }
quests[1147] = { id = 1147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwarm wächst", description = "Hmm. Offenkundig hält Belgrom die Monster für eine Bedrohung. Er möchte, dass sie in die Tiefen zurückgedrängt werden, aus denen sie gekommen sind.\n\nDie Zwerge zu töten, die von der Forscherliga geschickt wurden, genügte wohl nicht - jetzt muss ich eine Gruppe halbtoter Krieger in einen neuen Kampf führen. Aber selbst können wir das nicht; nicht unter diesen Bedingungen. Die Grabungsstätte liegt südlich von hier. Es sollten keine Zwerge mehr in der Gegend sein. Habt Ihr Lust, Klinge oder Stab in die Hand zu nehmen und uns zu unterstützen?", sourceObjective = "Tötet 5 Silithidsucher, 5 Silithidschwarmdrohnen sowie 5 Silithideindringlinge und kehrt zu Moktar Krin in Tausend Nadeln zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1148] = { id = 1148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parts of the Swarm" }
quests[1149] = { id = 1149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test des Glaubens", description = "Ihr habt mich also gesucht, oder führt Euch das Schicksal zu mir? Einerlei. Ihr seid jetzt hier, und so wird Eure Reise erneut beginnen.\n\nDas Sein besteht aus vielen Aspekten: Geist, Körper, Verstand. Einige davon kann man anhand der Traditionen einer Kultur bewerten. Von anderen können wir nur hoffen, dass sie in uns selbst existieren. Wenn Ihr einverstanden seid, möchte ich einige der Aspekte in Euch testen.\n\nWenn Ihr besteht, werdet Ihr stärker werden. Wenn Ihr scheitert, werdet Ihr die Weite des Nether begreifen.\n\nAls Erstes ein Test des Glaubens.", sourceObjective = "Wenn Ihr festen Glaubens seid, dann springt von den Planken über Tausend Nadeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[1150] = { id = 1150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test der Belastbarkeit", description = "Ich sehe mit Freuden, dass Euer Mut im Lichte Eurer bisherigen Taten unerschütterlich bleibt. Da Euer Glaube stark ist, wird es Zeit, Euren Körper zu testen.\n\nAls Erstes ein Test der Belastbarkeit. Geht zum Bau der Wildfedern westlich vom Freiwindposten. Steigt in die Tiefen ihres Unterschlupfes hinab und zerstört ihre Nahrungsvorräte. Damit solltet Ihr deren Zorn angestachelt haben. Wenn Ihr lange genug überlebt, wird Grenka Blutkreischer Euch persönlich heimsuchen. Tötet sie und bringt mir ihre Klaue, um den Test abzuschließen.", sourceObjective = "Bringt Grenkas Klaue zu Dorn Ebenenpirscher in Tausend Nadeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[1151] = { id = 1151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test der Kraft", description = "Zu Zeiten der Alten Götter bewohnten Elementare einen Großteil dieser Welt. Sie beteten die Alten Götter an, und die Götter fesselten die Elementare durch ihre Macht an diese Welt. Als die Alten Götter verbannt wurden, verblassten die Elementare in unserer Welt und kehren jetzt auf Geheiß mächtiger Magier zurück.\n\nAber es gibt Ausnahmen. Einige Elementare waren mächtig genug, aus eigenen Stücken hier zu bleiben. Solch ein Elementar ist Rok'Alim.\n\nSucht Rok'Alim in Tausend Nadeln und tötet ihn, um Eure Kraft zu beweisen.", sourceObjective = "Bringt Fragmente von Rok'Alim zu Dorn Ebenenpirscher in Tausend Nadeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[1152] = { id = 1152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test der Lehre", description = "Eure Zeit bei mir neigt sich dem Ende zu. Ich bin wissend, aber den Test der Lehre kann ich Euch nicht stellen. Es gilt, Lektionen zu erlernen und Orte zu besuchen, die in der Zuständigkeit anderer liegen.\n\nWenn Ihr bereit seid, dann sucht Braug Dämmergeist auf - er ist ein höchst weiser Schamane. Er wird Euch weiter testen, also achtet auf seine Worte, {name}.\n\nWenn Ihr bereit seid, dann sucht den Tunnel, der das Steinkrallengebirge mit dem Eschental verbindet. Dort in der Nähe lebt Braug. Und seid vorsichtig, {name}, die Nachtelfen versuchen vielleicht, Euren Test zu behindern.", sourceObjective = "Sucht Braug Dämmergeist in der Nähe des Eingangs zum Steinkrallenpfad im Steinkrallengebirge.", sourceObjectiveStatus = "unverified-source-field" }
quests[1153] = { id = 1153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine neue Erzprobe", description = "{class}, Ihr habt mir auch früher schon geholfen. Der Kriegshäuptling ist mit meinen bisherigen Leistungen zufrieden und bittet mich, mit neuer Entschlossenheit fortzufahren. Meine Ehre gebietet, dass ich den Kriegshäuptling wissen lasse, was Ihr alles vollbracht habt, doch zuvor möchte ich Euch abermals um Hilfe bitten.\n\nJüngst kamen Reisende aus dem Süden von einem Ort namens Tausend Nadeln. Dort töteten sie einen Kobold, der eine außergewöhnliche Erzprobe bei sich hatte, wollten sie aber nicht verkaufen. Ich möchte eine Probe dieses Erzes untersuchen.", sourceObjective = "Sucht eine unbearbeitete Erzprobe bei einem Buddler oder Feldmesser der Bruchschnauzen und bringt sie zu Tatternack Stahlformer im Camp Taurajo im Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[1154] = { id = 1154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test der Lehre", description = "Ihr habt Dorns Tests bestanden und wollt jetzt Eure nächste Prüfung absolvieren. Sehr gut. Bisher sind alle Eure Herausforderungen kindisch gewesen. Es ist leicht, Euren Körper zu testen - bei Eurem Verstand sieht das schon anders aus.\n\nIch werde es mit einfachen Worten erklären: sucht das Buch, das ich Euch nenne, lest es und beantwortet meine Fragen nach seinem Inhalt.\n\nWas für ein Buch, werdet Ihr fragen? Das 'Vermächtnis der Aspekte'. Man findet es in den Tiefen des Grabhügels von Dor'Danil im südlichen Eschental, wo es von den toten Druiden und deren Tötern bewacht wird.", sourceObjective = "Sucht das 'Vermächtnis der Aspekte' und bringt es zu Braug Dämmergeist in der Nähe des Eingangs zum Steinkrallenpfad im Steinkrallengebirge zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1159] = { id = 1159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test der Lehre", description = "Gut gemacht, {name}. Ihr habt den ersten Teil des Tests der Lehren bestanden, aber es bleibt noch eine Frage zu beantworten. Aber es ist nicht an mir, diese Frage zu stellen.\n\nBesucht Parqual Fintallas in Lordaeron. Er war ein bedeutender Historiker der Menschen, bevor die Seuche ihn erwischte. Jetzt sucht er immer noch Erleuchtung, freilich einer ganz anderen Art.\n\nEr wird eine weitere Forderung an Euch stellen, bevor er Euch etwas fragt, aber Ihr habt Euch bisher meisterhaft geschlagen - ich bin sicher, Ihr werdet dieses Hindernis überwinden.", sourceObjective = "Sucht Parqual Fintallas in Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1160] = { id = 1160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test der Lehre", description = "Ich sage Euch, was Ihr suchen müsst und werde Euch sogar meine Frage stellen, aber nicht, weil Ihr Euch beweisen wollt. Wissen ist weit wichtiger als Kraft. Auch wenn andere Euch in ihren Fähigkeiten überlegen sein mögen, Euer Wissen über die Welt ist wertvoller.\n\nGeht zu dem Kloster im Norden Tirisfals. In der dortigen Bibliothek steht ein Buch mit dem Titel Die Anfänge der Bedrohung durch die Untoten. Es wurde von den jetzt verderbten Paladinen benutzt, um sie in meiner Art des Kampfes auszubilden.\n\nBringt es mir.", sourceObjective = "Sucht Die Anfänge der Bedrohung durch die Untoten und bringt es zu Parqual Fintallas in Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1164] = { id = 1164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Dieben stehlen", description = "Die Hure! Das Flittchen! Kenata lebt noch; ihre Familie blüht und gedeiht, während ich leide. Verlassene, wahrhaftig!\n\nMeine Familie wurde Opfer der Seuche. Unser Besitz ebenfalls dahin, während des Kriegs geplündert und niedergebrannt. Und nach alledem haben sie und ihre lausigen Kinder die Stirn, das einzig Kostbare zu stehlen, das ich noch hatte.\n\nMir sind die Sachen, die sie gestohlen haben, längst einerlei. Ich möchte ihre Köpfe!\n\nTötet sie für mich! Geht zum Bauernhof der Dabyries in Arathi, nordöstlich der Zuflucht.", sourceObjective = "Bringt Kenata, Fardel und Marcel Dabyries Köpfe zu Genavie Kahler in Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1166] = { id = 1166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oberanführer Mok'Morokks Sorgen", description = "Verbeugen Euch vor Oberanführer Mok'Morokk!\n\nRexxar mich machen zu mächtigem Anführer von Steinbrecherklan!\n\nIch gut Anführer. Ich Klan sicher machen.\n\nGroße Drachen kommen und machen Feuer in alte Heimat. Ich klug Oger. Finden neu Heimat für Klan hier.\n\nAlte Heimat so schnell verlassen, ich Sachen vergessen. Winzig {race}, gehen mein Sachen holen. Gehen nach Süden und suchen mein lecker Grog, mein Schnupftabak und mein Geldkassette. Ich Euch mögen, wenn Ihr das tun. Ihr in Flammenbau und Ruinen der Steinbrecher schauen... sie dort sein, ich sicher!", sourceObjective = "Oberanführer Mok'Morokk in Brackenwall möchte, dass Ihr seinen Grog, seinen Schnupftabak und seine Geldkassette aus dem Sumpf der Düstermarschen holt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1167] = { id = 1167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Turm von Althalaxx", description = "Bevor Ihr Athrikus konfrontiert, wäre es vermutlich klug, Balthule zu konsultieren. Zweifellos ist er bei seiner Wacht über den Turm sehr aufmerksam gewesen und könnte Informationen über jüngste Entwicklungen haben.", sourceObjective = "Sprecht mit Balthule Schattenhieb beim Turm von Althalaxx.", sourceObjectiveStatus = "unverified-source-field" }
quests[1168] = { id = 1168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armee des schwarzen Großdrachen", description = "Mok'Morokk wurde von Rexxar zum Oberanführer gemacht. Ihm liegt mehr an Macht als an den Ogern.\n\nSchwarze Großdrachen töten viele Oger. Töten Thargs Frau. Mok'Morokk sagt uns, wir müssen fliehen. Lässt uns hierher kommen.\n\nOger sollten kämpfen. Oger nicht gut im Weglaufen. Mok'Morokk schert sich nur um Mok'Morokk.\n\nFür mich die Ruinen der Steinbrecher Heimat. Mir gefallen im Süden. Dieser Ort nicht Heimat.\n\nHelft Ogern, Armee der schwarzen Großdrachen zu bekämpfen. Ich wollen Rache. Ich wollen nach Hause.", sourceObjective = "Tharg in Brackenwall möchte, dass Ihr 10 Späher der Feuermähnen, 10 Aschenschweife der Feuermähnen und 5 Bannschuppen der Feuermähnen tötet.", completion = "Ihr tötet viele der Armee der schwarzen Großdrachen. Ihr mutiger {race}.\n\nMacht Tharg glücklich.", sourceObjectiveStatus = "unverified-source-field" }
quests[1169] = { id = 1169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brut identifizieren", description = "Während der törichte Narr Mok'Morokk seine Macht genießt und Tharg mit den Dämonen des Kummers und der Rache ringt und um die Führerschaft des Klans buhlt, scheine ich der Einzige zu sein, der die Ursache der Aggression in unserer alten Heimat herausfinden möchte.\n\nWarum der verwirrte Blick, {name}? Erwartet Ihr, dass ich wie ein tumber Grobian spreche, nur weil ich ein Oger bin?\n\nDoch zurück zum Geschäft, bringt mir die Herzen und Zungen der Welpen und Jungtiere. Ich werde die Wurzel dieses Übels finden...", sourceObjective = "Draz'Zilb in Brackenwall hätte gern, dass Ihr ihm 7 sengende Zungen und 7 sengende Herzen bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1170] = { id = 1170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brut von Onyxia", description = "Das Dorf der Steinbrecher wurde von der Brut von Onyxia überrannt. Aber warum sollte die Tochter des schwarzen Drachenlords Todesschwinge über unser Land herfallen?\n\nDas ist sehr beunruhigend. Gewiss wurde Onyxia aus einem anderen Grund hergeschickt, als eine kleine Schar von Ogern zu belagern.\n\nVerständigt unverzüglich Mok'Morokk! Es muss gehandelt werden.", sourceObjective = "Sprecht mit Oberanführer Mok'Morokk in Brackenwall.", sourceObjectiveStatus = "unverified-source-field" }
quests[1171] = { id = 1171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brut von Onyxia", description = "Ihr lasst mich jetzt in Ruhe. Sagt Draz'Zilb, wir bleiben hier. Keine schwarzen Großdrachen hier.", sourceObjective = "Sprecht mit Draz'Zilb in Brackenwall.", sourceObjectiveStatus = "unverified-source-field" }
quests[1172] = { id = 1172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brut von Onyxia", description = "Onyxias Brut wurde über das Drachendüster verstreut. Es dürfen auf keinen Fall weitere Welpen schlüpfen.\n\nBegebt Euch eilig zum Drachensumpf in den Düstermarschen. Gewiss hat sie dort einen Hort angelegt. Sucht die Eier der bösen Großdrachen und vernichtet sie.\n\nWir können das Dorf der Steinbrecher nie zurückerobern, wenn das Umland eine Brutstätte bleibt.\n\nWas Mok'Morokk angeht... für den Jammerlappen habe ich andere Pläne.", sourceObjective = "Draz'Zilb in Brackenwall möchte, dass Ihr 5 Eier von Onyxia zerstört.", sourceObjectiveStatus = "unverified-source-field" }
quests[1173] = { id = 1173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fordert Oberanführer Mok'Morokk heraus", description = "Ihr wagt es, Oberanführer Mok'Morokk herauszufordern?\n\nHa!\n\nIch zerschmettern einen Winzling von {race}!\n\nIhr mir sagen, wenn bereit für ordentliche Tracht Prügel.", sourceObjective = "Besiegt Mok'Morokk und bringt die Nachricht zu Draz'Zilb in Brackenwall.", sourceObjectiveStatus = "unverified-source-field" }
quests[1174] = { id = 1174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gnome gewinnen!" }
quests[1175] = { id = 1175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Straßenunebenheit", description = "Nach dem schweren Zusammenstoß des Red-Thunder-Rennwagen der Goblins und einem Basilisken hat Kronkreiter mich angeheuert, um die Strecke zu warten. Keine Ahnung, was die Tiere in der Ebene fressen, dass sie so groß werden, aber wir müssen sie dezimieren, damit sie nicht auf die Fahrbahn laufen, wenn ein Rennen stattfindet.\n\nIch sag Euch was. Wenn ihr ein wenig Profit machen wollt, zieht los und entfernt die Basilisken aus der Gegend.", sourceObjective = "Tötet 10 Salzsteinbasilisken, 10 Salzsteinkristallhäute und 6 Salzsteinstarrer für Rennsteckenleiter Zherin in der Schimmernden Ebene.", sourceObjectiveStatus = "unverified-source-field" }
quests[1176] = { id = 1176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewicht reduzieren", description = "Wenn es um Rennen geht, zählt jede Kleinigkeit! Ob es sich nun um ein leises Quietschen der Kraftübertragung, eine geringfügige Schwäche der Stoßdämpfer oder ein leichteres Gewicht der Karosserie handelt, man muss alles berücksichtigen.\n\nWir benutzen Geierknochen für kleinere Modifikationen am Chassis unserer Rennwagen, die das perfekte Gleichgewicht zwischen Stärke und Gewicht haben. Und sie sind, was noch besser ist, leicht zu beschaffen, da es in der Salzwüste von Geiern wimmelt.\n\nBringt mir ein paar und ich zahle einen guten Preis dafür.", sourceObjective = "Beschafft 10 hohle Geierknochen für Pozzik in der Schimmernden Ebene.", sourceObjectiveStatus = "unverified-source-field" }
quests[1177] = { id = 1177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunger!", description = "Patsch großer Oger.\n\nIch hungrig.\n\nGeht Fische hauen. Bringt Patsch Essen.\n\nIhr füttert Patsch oder Patsch frisst Euch.", sourceObjective = "Schlammpatsch Dreckfuß in den nördlichen Düstermarschen möchte 8 Schlammflossenköpfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[1178] = { id = 1178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblinsponsoring", description = "Unser Rennfahrerteam ist der Stolz aller Goblins. Ihr wärt überrascht, welche Leute unser Team auf die eine oder andere Weise unterstützen.\n\nKennt Ihr Gazlowe? Er treibt auf der ganzen Welt Ersatzteile für uns auf. Er kam sogar mal her, um an einer unserer Aufhängungen zu arbeiten!\n\nVor ein paar Wochen wollte er uns den Prototyp einer neuen Treibstoffeinspritzpumpe schicken, aber sie ist noch nicht eingetroffen. Sonst ist er immer zuverlässig...Würde es Euch vielleicht etwas ausmachen, nach Ratschet zu gehen und ihn danach zu fragen? Ich will ja nicht drängen, aber die Gnome holen langsam auf!", sourceObjective = "Sprecht mit Gazlowe in Ratschet im Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[1179] = { id = 1179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brüder Kupferbolz", description = "Schon von der Schimmernden Ebene gehört, ja? Das ist eine Salzwüste drüben in Kalimdor, direkt südlich vom Canyon der Tausend Nadeln. Der ideale Austragungsort für Rennen, weil es da so flach ist!\n\nDa draußen sind zwei Gnomenbrüder, Freunde von mir, die ihren neuen Raketenwagen erproben, und soweit ich gehört habe, ist er schnell! Hey, so schnell, dass die Fahrer immer verunglücken. Und Gehirnerschütterungen bekommen.\n\nDarum baten sie mich um ein paar Helme für Belagerungsmaschinen, aber ich kann hier nicht weg, meine Pflicht fesselt mich an diesen Ort. Ich kann die Reise also nicht machen!\n\nKönnt Ihr es?", sourceObjective = "Bringt die Kiste mit Schutzhelmen zu Wizzel Kupferbolz. Zu finden ist er an der Illusionenrennbahn in Tausend Nadeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[1180] = { id = 1180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblinsponsoring", description = "Zurück zum Grund Eures Hierseins. Ich weiß, ich habe Pozzik versprochen, dass ich ihm eine neue Treibstoffeinspritzpumpe schicke, aber ich habe sie selbst noch nicht bekommen. Revilgaz drüben in Beutebucht sagte, er würde sie herschicken, aber irgendwie scheint da was schief gelaufen zu sein.\n\nWenn das stimmt, können wir wenig dagegen tun. Aber wir können wenigstens herausfinden, wann sie von Beutebucht abgeschickt wurde.\n\nFragt drüben bei Werftmeister Lozgil nach, er müsste die Frachtbriefe überprüfen können.", sourceObjective = "Sprecht mit Werftmeister Lozgil in Beutebucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[1181] = { id = 1181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblinsponsoring", description = "Ich fürchte, ich kann Euch nicht weiterhelfen, {name}. Wenn Ihr der Sache weiter nachgehen möchtet, würde ich vorschlagen, Ihr geht zum Baron persönlich. Wenn jemand über die Geschäfte von Revilgaz Bescheid weiß, dann Revilgaz selbst.\n\nIhr findet ihn in der Taverne jenseits des Hafens, Obergeschoss.", sourceObjective = "Sprecht mit Baron Revilgaz in Beutebucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[1182] = { id = 1182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblinsponsoring", description = "Wisst Ihr, die Schredder der Venture Company draußen am Nazferitisee (im Norden des Schlingendorntals) wurden mit einer neuartigen Treibstoffeinspritzpumpe ausgerüstet. Ich dachte mir, Pozzik könnte Kapital daraus schlagen, wenn er einige Einzelheiten erfahren könnte. Leider scheint Cozzle, der dortige Großknecht, etwas schlauer zu sein, als ich ihm zugestehen wollte.\n\nAber Ihr seht aus, als könntet Ihr es schaffen, die Blaupausen zu finden. Ich weiß, dass er sie in seinem Haus aufbewahrt, aber mit Sicherheit verschlossen und verriegelt.", sourceObjective = "Bringt die Treibstoffreglerblaupausen zu Baron Revilgaz in Beutebucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[1183] = { id = 1183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblinsponsoring", description = "Ihr solltet zum Aufbruch bereit sein. Bestellt Pozzik schöne Grüße und sagt ihm, wenn er etwas braucht, soll er keine Hemmungen haben, zu fragen. Ich warte auf die baldige Nachricht, dass er den Streckenrekord gebrochen hat!", sourceObjective = "Bringt die Blaupausen der Treibstoffeinspritzpumpe zu Pozzik in der Schimmernden Ebene.", sourceObjectiveStatus = "unverified-source-field" }
quests[1184] = { id = 1184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teile des Schwarms", description = "Geht zurück zu Belgrom in Orgrimmar und sagt ihm, dass Moktar in Tausend Nadeln ganz in seinem Sinne handelt. Sagt ihm auch, dass meine Studien voranschreiten und ich hoffe, dass ich bald mehr gelernt habe. Das sollte ihn freuen.", sourceObjective = "Kehrt zu Belgrom Felshammer in Orgrimmar zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1185] = { id = 1185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter dem Chitin war..." }
quests[1186] = { id = 1186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der achtzehnte Rennfahrer", description = "Ich werde damit beschäftigt sein, diese neue Treibstoffeinspritzpumpe in unsere Rennwagen einzubauen, aber wenn Ihr dem Team noch weiter helfen möchtet, sprecht mit Razzeric. Er ist unser Fahrer - unser achtzehnter Fahrer, um genau zu sein -, und er nimmt selbst gern Veränderungen an den Rennwagen vor.\n\nAber er ist ein wenig daneben, bemüht Euch daher, nicht zu überrascht zu wirken.", sourceObjective = "Sprecht mit Razzeric in der Schimmernden Ebene in Tausend Nadeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[1187] = { id = 1187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Razzerics Basteln", description = "Pozzik ist ein toller Mechaniker, das weiß ich, aber er hat Angst davor, einfach was mit viel Power einzubauen und dann loszudüsen. Aber ich nicht.\n\nWenn Pozzik mit einem Rennwagen fertig ist, nehme ich mir die Zeit und baue eigene Veränderungen ein - Ihr wisst schon, die Steuerung lockern, Teile des Rahmens entfernen und ihm mehr Saft geben!\n\nIch habe einen Zephyriumnachbrenner von Kainer im Gizmorium in Gadgetzan bestellt, aber offenbar musste der Zeppelin, mit dem er geschickt wurde, in den Düstermarschen notlanden! Ich muss das Ding haben, {name}!", sourceObjective = "Bergt den Zephyriumnachbrenner für Razzeric in der Schimmernden Ebene.", sourceObjectiveStatus = "unverified-source-field" }
quests[1188] = { id = 1188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherheit zuerst", description = "Doch wartet, was ist das? Kainer hat die Sicherung aktiviert gelassen. Das reduziert die Menge Energie, die ich aus dem Nachbrenner rausholen kann. Ich sagte ihm, ich wollte sie deaktiviert haben! Das ist nicht gut.\n\nIhr müsst das ins Gadgetzan-Gizmorium in der Tanariswüste bringen und es von Kainer entfernen lassen.", sourceObjective = "Bringt den Zephyriumnachbrenner zu Kainer nach Gadgetzan in Tanaris.", sourceObjectiveStatus = "unverified-source-field" }
quests[1189] = { id = 1189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherheit zuerst", description = "So, ich habe getan, was Razzeric wollte. Sagt ihm nur, er soll vorsichtig sein, wenn er das zündet. Wenn er den kleinsten Fehler macht, fährt er nicht los, sondern ist nur noch ein Brandfleck auf der Rennstrecke.\n\nWäre doch ein Jammer, wenn das passiert. Wer weiß, ob unser neunzehnter Fahrer genauso gut wäre?", sourceObjective = "Bringt den umgebauten Zephyriumnachbrenner zu Razzeric. Zu finden ist er in der Schimmernden Ebene in Tausend Nadeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[1190] = { id = 1190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tempo halten", description = "Die Kupferbolz-Brüder haben einen neuen Baustoff entdeckt, das ist die einzig logische Erklärung. Ihre Rennwagen fahren schneller als vorher, aber Design und alle anderen Daten ihrer Probefahrten sind noch dieselben.\n\nWir wissen, dass Rizzel Kupferbolz sich fast ununterbrochen mit den Plänen seiner neuen Entdeckung befasst hat.\n\nZamek kann ein Ablenkungsmanöver inszenieren, damit Ihr diese Pläne von ihnen stehlen könnt.", sourceObjective = "Lasst Zamek ein Ablenkungsmanöver inszenieren und stehlt dann Rizzels Pläne für Pozzik in der Schimmernden Ebene in Tausend Nadeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[1191] = { id = 1191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zameks Ablenkungsmanöver" }
quests[1192] = { id = 1192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Induriumerz" }
quests[1193] = { id = 1193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine beschädigte Falle" }
quests[1194] = { id = 1194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rizzels Baupläne", description = "Rizzels Baupläne beschreiben den Vorgang der Veredelung von Induriumerz. Man kann dem Gekritzel entnehmen, dass Induriumerz an der Ausgrabungsstätte Uldaman der Zwerge im Ödland zu finden ist.\n\nDie anderen Notizen behandeln fast ausschließlich seinen Hitzewiderstand.\n\nAls Briefbeschwerer der Pläne dient ein Klumpen, der wie unbearbeitetes Induriumerz aussieht.", sourceObjective = "Bringt die Induriumerzprobe zu Pozzik. Zu finden ist er in der Schimmernden Ebene in Tausend Nadeln.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[1195] = { id = 1195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die heilige Flamme", description = "Die Galakzentauren von Tausend Nadeln beschützen ein Artefakt aus der Zeit der Erschaffung der Zentauren.\n\nWir würden es gern bergen, benötigen aber eine Phiole Wasser aus einem der Mondbrunnen der Nachtelfen.\n\nUm dieses Wasser zu beschaffen, müsst Ihr zuerst eine Phiole besorgen, wie sie die Dryaden beim Rajenbaum im Herzen des Eschentals besitzen. Am Westufer des Falfarren, südlich der Hauptstraße, befindet sich ein Mondbrunnen, in dem Ihr die Phiole füllen könnt.", sourceObjective = "Bringt eine gefüllte geätzte Phiole zu Zangen Steinhuf in Donnerfels.", sourceObjectiveStatus = "unverified-source-field" }
quests[1196] = { id = 1196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die heilige Flamme", description = "Bringt die gefüllte Phiole zu Rau Klippenläufer beim Freiwindposten im Südosten von Tausend Nadeln. Ihr gelangt nach Tausend Nadeln, wenn Ihr den Großen Aufzug am Südrand des Brachlandes benutzt.\n\nIch wäre nicht überrascht, wenn Ihr uns weiter behilflich sein könntet.", sourceObjective = "Bringt die gefüllte geätzte Phiole zu Rau Klippenläufer im Freiwindposten.", sourceObjectiveStatus = "unverified-source-field" }
quests[1197] = { id = 1197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die heilige Flamme", description = "Wenn Ihr das Wasser benutzt, das Ihr mitgebracht habt, könnt Ihr vorübergehend die Flamme löschen, die das Zentaurenrelikt schützt. Aber der Effekt ist nicht von Dauer, daher müsst Ihr rasch handeln.\n\nIhr findet die Spalthufklippe, die Festung der Zentauren, nördlich von hier. Die Flamme wird in der Spalthufhöhle bewahrt, einem schwer bewachten Teil der Klippe.\n\nAber seid vorsichtig, die Zentauren der Galak sind dort in großer Zahl zugegen und dürften etwas, das ihnen so teuer ist, nicht freiwillig hergeben.", sourceObjective = "Holt den gespaltenen Huf für Rau Klippenläufer im Freiwindposten.", sourceObjectiveStatus = "unverified-source-field" }
quests[1198] = { id = 1198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach Thaelrid", description = "Heutzutage kursieren viele Gerüchte über die Vereinigung des Schattenhammers mit den Naga in der Tiefschwarzen Grotte im Westen.\n\nMeine Rolle hier besteht darin, so viele Informationen wie möglich zu sammeln, damit wir wissen, wann und wo Hilfe erforderlich ist.\n\nEs ist jetzt Wochen her, seit ich einen Späher losschickte, um die Aktivitäten in der Tiefschwarzen Grotte auszuspähen. Späher Thaelrid hat sich noch nicht zurückgemeldet.\n\nMeine anderen Späher sind mit dringenden Angelegenheiten beschäftigt.\n\nSucht nach Thaelrid für mich, {name}.", sourceObjective = "Sucht Späher Thaelrid in der Tiefschwarzen Grotte auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[1199] = { id = 1199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stunde der Finsternis", description = "Mit der Macht der uralten Rituale der chaotischen Alten Götter versuchen die Mitglieder des Schattenhammers, ihre dunklen Schutzherren zurückzuholen und Tod und Schrecken in der Welt zu verbreiten.\n\nWir glauben, dass der Schattenhammer sich mit den Naga verbündet hat und sich ihre Anhänger in der Tiefschwarzen Grotte im Westen zusammenrotten.\n\nWelch schändliche Pläne in den Tiefen des alten Tempels auch immer geschmiedet werden, wir müssen sie vereiteln.\n\nFührt Krieg gegen die Anhänger des Schattenhammers und bringt Beweise Eurer Taten mit. Eure Bemühungen sollen reich belohnt werden.", sourceObjective = "Bringt 10 Zwielichtanhänger zu Schildwache Aluwyn im Stützpunkt an der Grotte.", sourceObjectiveStatus = "unverified-source-field" }
quests[1200] = { id = 1200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schurkerei in der Tiefschwarzen Grotte", description = "Die Kraft hat mich verlassen. Ich benötige Eure Hilfe!\n\nDiese Stätte war einst ein großer Tempel von Elune. Doch das Unglück führte zum Untergang, als die Verderbnis eines Alten Gottes unter der Erde emporwallte und den heiligen Mondbrunnen besudelte.\n\nAku'mai, die Dienerin der Alten Götter, erhob sich aus den Wassern.\n\nDie Kultisten des Schattenhammers haben sich mit den Naga verschworen, um diese Anlage zu besetzen. Die Kultisten opfern unter Führung von Kelris Unschuldige für Aku'mai, um Macht zu erlangen.\n\nBitte, erschlagt Kelris und bringt Ashelan im Stützpunkt an der Grotte seinen Kopf, {name}.", sourceObjective = "Bringt den Kopf von Zwielichtfürst Kelris zu Ashelan Nordwald im Stützpunkt an der Grotte.", sourceObjectiveStatus = "unverified-source-field" }
quests[1201] = { id = 1201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Theramores Spione", description = "Die Horde und die Allianz wahren einen brüchigen Waffenstillstand. Beide Seiten liefern sich Scharmützel und heimliche Angriffe. Wir müssen dafür sorgen, dass die Horde stets die Oberhand behält!\n\nJetzt haben wir die Chance, genau das zu tun.\n\nSpitzel der Allianz haben Stellungen östlich des Dorfs Brackenwall bezogen. Sie spionieren das Dorf aus und melden unsere Bewegungen Theramore, was wir nicht dulden können.\n\nJagt die Spitzel und schaltet sie aus. Schickt eine deutliche Botschaft an ihre Vorgesetzten, dass wir die Anwesenheit ihrer Spione nicht dulden!", sourceObjective = "Tötet 9 Spitzel von Theramore und kehrt dann zu Nazeer Blutlanze in Brackenwall zurück.", completion = "Gute Arbeit. Ihre Spitzel sind geschickt, aber nicht gut genug, den wachsamen Blicken der Horde zu entkommen!", sourceObjectiveStatus = "unverified-source-field" }
quests[1202] = { id = 1202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Docks von Theramore", description = "{name}, zwei unserer Spione wurden ausgeschickt, um Dokumente von einem Schiff bei den Docks von Theramore zu stehlen. Sie bekamen die Papiere, wurden aber entdeckt und waren gezwungen, die Dokumente ins Meer zu werfen.\n\nSpäter konnte ein Spion entkommen, die Beute aber nicht bergen. Er informierte mich über sein Scheitern und jetzt gebe ich Euch die Aufgabe.\n\nDie Dokumente sind in einer Schließkiste irgendwo im Wasser unter den Docks von Theramore. Sucht diese Dokumente, {name}, und bringt sie mir.", sourceObjective = "Bringt die Dokumente des Kapitäns zu Nazeer Blutlanze in Brackenwall.", progress = "Habt Ihr die Dokumente gefunden, {name}? Sie enthalten Informationen, die wichtig für die Stabilität der Allianz, und damit auch wichtig für die Sicherheit der Horde sind.", completion = "Ich bewundere Euch, {name}. Dies war keine leichte Mission. Aber die Dokumente, die Ihr gerettet habt, werden von unseren Vorgesetzten hoch geschätzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1203] = { id = 1203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jarl braucht eine Klinge", description = "Ich habe zu schneiden. Ich kann Euch nicht sagen, was ich schneiden werde, aber... Ich brauche eine Klinge. Eine ganz bestimmte Klinge...\n\nManche Leute sprechen von einem Schwert. Ich nenne es eine Schwingklinge.\n\nHelft Ihr mir? Diese Fischmenschen, Murlocs, oder wie auch immer die heißen... Einer von ihnen wird Messerwirbel genannt, hat ständig so ein großes Schwert bei sich, lebt nördlich von hier am Strand. Ich brauche sein Schwert!\n\nAber schlaft nicht noch darüber. Was ich schneide, das hält nicht ewig...", sourceObjective = "Bringt Messerwirbels Schwert zu \"Sumpfauge\" Jarl im Irrlichtanwesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1204] = { id = 1204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlammpanzersuppe mit Käfern", description = "Ich arbeite an einem Gericht namens \"Schlammpanzersuppe mit Käfern\". Die wichtigsten Zutaten fehlen mir leider noch immer... aber ich glaube nicht, dass ich einen Fußmarsch durch die Düstermarschen durchhalten könnte.\n\nNun denn, {name}, könntet Ihr für mich auf die Jagd gehen? Als Erstes brauche ich die Zungen von Schlammpanzerschildkröten. Ihr findet die Schlammpanzer entlang der Küste, hauptsächlich im Bereich der Bucht.\n\nAber ich will nicht jede beliebige Zunge! Ich habe gehört, dass die Zungen von einigen Schlammpanzerschildkröten gespalten sind...\n\nMan sagt, diese gespaltenen Zungen hätten einen charakteristischen Geschmack, und den möchte ich in meinem Gericht...", sourceObjective = "Bringt Morgan Stern in Theramore 8 gespaltene Schlammpanzerzungen.", progress = "Habt Ihr die gespaltenen Zungen gefunden?", completion = "Diese sind ganz exzellent! Danke, {name}!\n\nJetzt werde ich versuchen, durch verschiedene Kochtechniken herauszufinden, wie ihr Geschmack am besten zur Geltung kommt.\n\nVielleicht werde ich ein Gericht kreieren, das des Blauen Eremiten in Sturmwind würdig ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[1205] = { id = 1205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlammwühler", description = "Schlammwühler ist ein uralter Krokilisk in den Düstermarschen. Und seine Zeit zum Sterben ist gekommen.\n\nAlte Knochen knirschen, wenn er seinen gewaltigen Leib durch den Sumpf schleppt, und auch wenn er sich noch mit der Kraft und dem Tempo der Jugend bewegt, martert sein alter Körper den großen innewohnenden Geist, ein Geist, dessen Flamme nicht erlischt.\n\nHeutzutage jedoch leidet er unablässig qualvolle Schmerzen. Ihr müsst das Leben dieser edlen Kreatur beenden, {name}. Ihr müsst Schlammwühler Frieden geben.", sourceObjective = "Bringt Schlammwühlers Zahn zu Melor in Donnerfels.", progress = "Habt Ihr den Zahn von Schlammwühler, {name}? Habt Ihr das Leiden der Kreatur beendet?", completion = "Sehr gut, {name}.\n\nIch bin sicher, die Jagd war nicht leicht, aber es ist gut zu wissen, dass der Schmerz des Tieres ein Ende gefunden hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[1206] = { id = 1206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jarl braucht Augen", description = "Augensaft ist ein leckeres Getränk. Leider haben die meisten Tierwesen nur zwei Augen.\n\nAber Spinnen haben eine Menge Augen. Jede Menge. Und Graunebelaugensaft ist lecker. Samtig und salzig! Unzerplatzte Spinnenaugen... Ich schmecke sie schon förmlich.\n\nGraunebelspinnen leben westlich von hier in den Graunebelhöhlen. Glaubt Ihr, die Spinnen wurden nach der Höhle benannt... oder ist es umgekehrt?", sourceObjective = "Bringt 20 unzerplatzte Graunebelaugen zu \"Sumpfauge\" Jarl im Irrlichtanwesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1218] = { id = 1218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marschenfroschschenkel", description = "Ich koche gern. Leckere Sumpfküche. Frittierte grüne Froschschenkel und dergleichen.\n\nLeider habe ich keine Froschschenkel mehr. Beim Anwesen wimmelt es nur so von Fröschen, riesigen Marschenfröschen. Könntet Ihr mir vielleicht ein paar dieser Schenkel bringen? Das ist halb so wild, ehrlich. Haut ihnen einfach auf den Kopf und bringt mir die Schenkel.\n\nDann mache ich einen Eintopf und topfe ihn ein und schlabber ihn aus und geb Euch auch was ab.\n\nMögt Ihr Eintopf?", sourceObjective = "Bringt 10 Marschenfroschschenkel zu \"Sumpfauge\" Jarl in den Düstermarschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1219] = { id = 1219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Orcbericht", description = "Beim Durchsuchen der lockeren Erde findet sich die abgetrennte Hand eines Orcs. Die Hand hält eine aus Knochen geschnitzte Röhre umklammert. Und in der Röhre befindet sich ein fleckiges Pergament.\n\nDas Pergament ist in der Sprache der Orcs verfasst... und sieht wichtig aus.", sourceObjective = "Bringt den Bericht des Spions zu Leutnant Aden in Theramore.", sourceObjectiveStatus = "unverified-source-field" }
quests[1220] = { id = 1220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hauptmann Mumm", description = "Hauptmann Mumm sollte den Orcbericht sehen, den Ihr gefunden habt, {name}. Er kennt die Sprache der Orcs besser als die meisten. Und er sollte wissen, dass sich Spione der Horde bei Theramore aufhalten!\n\nDer Hauptmann befindet sich in der Kaserne auf der nordöstlichen Seite der Insel Theramore.", sourceObjective = "Bringt den Bericht des Spions zu Hauptmann Garran Mumm.", sourceObjectiveStatus = "unverified-source-field" }
quests[1221] = { id = 1221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blaulaubknollen", description = "Blaulaubknollen gelten auf der ganzen Welt als Delikatesse! Aber sie sind rar, sehr rar. Man findet sie nur hier im Brachland, tief in der Erde des Krals der Klingenhauer.\n\nUnd selbst dann sind sie fast nicht zu finden, wenn man nicht weiß, wo man suchen muss! Darum habe ich diese Schnüffelnasenziesel abgerichtet, damit sie sie für mich aufstöbern. Sie haben unheimlich empfindliche Nasen und riechen eine Knolle aus fünfzig Schritt Entfernung.\n\nEs wird nicht einfach sein, aber wenn Ihr mir ein paar Knollen bringt, bezahle ich Euch gut dafür.", sourceObjective = "Schnappt Euch eine Kiste mit Löchern.\nSchnappt Euch einen Schnüffelnasenleitstecken.\nSchnappt Euch das Handbuch für Schnüffelnasenbesitzer und lest es.\n\nBenutzt im Kral der Klingenhauer die Kiste mit Löchern, um ein Schnüffelnasenziesel zu beschwören, und benutzt den Leitstecken bei dem Ziesel, damit es nach Knollen sucht.\n\nBringt 6 Blaulaubknollen, den Schnüffelnasenleitstecken und die Kiste mit Löchern zu Mebok Mizzyrix in Ratschet.", sourceObjectiveStatus = "unverified-source-field" }
quests[1222] = { id = 1222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stinkis Flucht", description = "Klasse, endlich etwas, das mich nicht essen möchte!\n\nIch brauche Hilfe mit den Tierwesen hier, und Ihr kommt gerade recht, <Jungchen/Lady>.\n\nDer Koch Morgan Stern arbeitet an einem neuen Rezept und hat mich hierher geschickt, um Sumpfbohnenblätter zu sammeln. Ich glaube, er findet sie lecker.\n\nWie auch immer, während ich nach einer Sumpfbohnenpflanze suchte... wurde ich umzingelt! Könnt Ihr mir hier raus helfen und auf mich aufpassen, während ich nach den Sumpfbohnen suche?", sourceObjective = "Begleitet \"Stinki\" Ignatz und sprecht dann mit Morgan Stern in Theramore.", completion = "Mr. Ignatz war gerade mit den Sumpfbohnenblättern hier und sagte mir, dass Ihr ihm echt aus der Klemme geholfen habt.\n\nDanke, {name}. Ich werde meinen Onkel bitten, dass er Euch ein Festmahl bereitet, wenn Ihr das nächste Mal den Blauen Eremiten in Sturmwind besucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[1238] = { id = 1238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Report" }
quests[1239] = { id = 1239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der abgetrennte Kopf", description = "Ausgiebiges Graben fördert den Kopf eines männlichen Orcs zu Tage, der am Hals abgesägt worden war. Seine Lippen sind zu einer höhnischen Grimasse verzerrt, seine dunklen Augen blicken trotzig.", sourceObjective = "Bringt den Kopf des aufsässigen Orcs zu Nazeer Blutlanze in Brackenwall.", sourceObjectiveStatus = "unverified-source-field" }
quests[1240] = { id = 1240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Trollhexendoktor", description = "Wir müssen die Umstände von Margs Tod erfahren! Und das können wir nur, {name}, durch die Hexenmagie der Trolle.\n\nBringt Margs Kopf zu Kin'weelay im Schlingendorntal im Basislager von Grom'gol.\n\nKin'weelay ist der mächtigste Hexendoktor der Dunkelspeertrolle. Wenn jemand mit Marg Nachtauges Geist sprechen kann, dann er.", sourceObjective = "Bringt den Kopf des aufsässigen Orcs zu Kin'weelay im Schlingendorntal im Basislager von Grom'gol.", sourceObjectiveStatus = "unverified-source-field" }
quests[1241] = { id = 1241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Diplomat", description = "Kürzlich wurde ein Diplomat nach Theramore geschickt, um sich mit Jaina Prachtmeer zu treffen. Dieser Diplomat kam nie an.\n\nIch glaube, die Defias sind in diese Verschwörung verwickelt, weiß aber nicht, wie. Das Verschwinden des Diplomaten wurde noch nicht publik, aber lange kann das nicht mehr so bleiben.\n\nAgenten des Königs durchkämmen die Stadt bereits nach Hinweisen, aber ich habe eigene Verbindungsleute, die ich gern einschalten würde.\n\nIm Tal der Helden lebt ein alter Freund von mir namens Jorgen. Sucht ihn, gebt ihm diese Notiz und folgt seinen Anweisungen.", sourceObjective = "Sucht Jorgen in der Stadt Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[1242] = { id = 1242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Diplomat", description = "Bringt diese Notiz zu Elling Trias. Sagt sonst nichts zu ihm. Seid nur höflich und wartet auf seine Antwort. Und keine Bange, er wird antworten.\n\nIch sage Euch das nur noch einmal, {name}: nehmt diese Sache ernst und haltet die Klappe.\n\nIhr findet Trias in seinem Käseladen, Trias' Käse, im Handelsdistrikt. Viel Glück.", sourceObjective = "Bringt Jorgens versiegelte Notiz zu Elling Trias in der Stadt Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[1243] = { id = 1243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Diplomat", description = "Jorgen, alter Pickel! Aha, so soll es also sein, hm?\n\nNa gut, damit kann ich leben. Ich hoffe, er findet den Wirbelnden Nether umso früher!\n\nSo wird es ablaufen, {name}. Ich werde meine Verbindungsleute hier kontaktieren, aber Ihr werdet den Großteil der Beinarbeit erledigen, damit ich ein wenig spare.\n\nGeht nach Dunkelhain im Dämmerwald und sucht Behüter Backus - er patrouilliert meist auf der Nordstraße vor der Stadt. Sagt ihm nur, dass Ihr für mich die Aktivitäten der Defias untersucht, dann wird er Euch mit allen verfügbaren Informationen weiterhelfen.", sourceObjective = "Gebt Behüter Backus im Dämmerwald die versiegelte Notiz.", sourceObjectiveStatus = "unverified-source-field" }
quests[1244] = { id = 1244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Diplomat", description = "Defiasaktivität? Es gibt immer etwas Aktivität; selbst wenn sie unter sich bleiben, betrachten wir sie als Bedrohung.\n\nAber jetzt, wo ich darüber nachdenke, kam es jüngst zu einer seltsamen Beobachtung. Es muss so zwei Wochen her sein, da hatten sich einige ihrer Agenten in Addles Siedlung versammelt. Dem Bericht glaubte ich zu entnehmen, dass etwas Großes vor sich ging.\n\nWarum seht Ihr da nicht zuerst nach und bringt mir alles, was Ihr findet?\n\nDer Bauernhof liegt südlich der Straße von Westfall direkt am Rand des Dämmerwalds.", sourceObjective = "Sucht die Liste der Defias und kehrt zu Behüter Backus im Dämmerwald zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1245] = { id = 1245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Diplomat", description = "Boah, das sieht zu komplex aus, um Euch nur auf eine falsche Fährte zu locken. Ich sollte das nicht einmal ansehen. Sprecht mit Trias - er kann es bestimmt verstehen. Und lasst Euch durch NICHTS aufhalten. Dies ist wichtiger als ich, vielleicht sogar wichtiger als er, aber wir werden sehen.\n\nUnd tut mir einen Gefallen, {name}, sagt keinem, dass ich Euch geholfen habe. Wenn meine Vorgesetzten erfahren, dass ich davon wusste und sie nicht informiert habe, hängen sie mich wahrscheinlich.", sourceObjective = "Bringt die Liste der Defias zu Elling Trias in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[1246] = { id = 1246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Diplomat", description = "Ja, jetzt, wo ich darüber nachdenke... Dashel... Dashel irgendwas... Wie war sein Name? FAUST! Dashel Steinfaust. In manchen Kreisen nennen sie ihn Faust - wahrscheinlich, weil er ein Raufbold ist.\n\nIhr könnt ihn normalerweise in der Altstadt finden - direkt mitten im Zentrum. Redet mit ihm. Wenn es sein muss, dann benutzt ein Schwert oder etwas Schweres und Stumpfes, um ihn zum Reden zu bringen. Und zögert nicht. Wenn er so tief drinsteckt, wie diese Papiere andeuten, wird er Euch freiwillig keine Informationen geben.", sourceObjective = "Sprecht mit Dashel Steinfaust in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[1247] = { id = 1247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Diplomat", description = "Ja, also... hm... Vielleicht weiß ich was über dieses Treffen in Addles Siedlung. Das war, glaube ich, vor ein paar Wochen. Ich hatte wirklich nichts damit zu tun. Meine Rolle war vorbei, als Plan A schief ging... verdammte Abenteurer.\n\nDer Kerl, den wir für Plan B hatten, kam aus Menethil; ein Typ namens Slim. Mehr weiß ich nicht über ihren Ersatzplan.", sourceObjective = "Sprecht mit Elling Trias in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[1248] = { id = 1248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Diplomat", description = "Ein Verbindungsmann von mir verbringt seinen Ruhestand in der Hafenstadt Menethil im Sumpfland. Er sollte Euch auf Euer Wort hin helfen, wenn Ihr ihm sagt, dass Ihr für mich arbeitet. Sein Name ist Mikhail. Bevor er Sturmwind vor ein paar Jahren verließ, erwähnte er, dass er Schankkellner werden wollte.\n\nSprecht mit ihm, sucht diesen Slim und findet heraus, ob es noch etwas über diesen entführten Diplomaten zu wissen gibt. Wir müssen herausfinden, wohin sie ihn gebracht haben, oder wenigstens, wer er ist. In der Liste steht nichts von ihren Plänen nach seiner Entführung.", sourceObjective = "Sprecht mit Mikhail im Sumpfland.", sourceObjectiveStatus = "unverified-source-field" }
quests[1249] = { id = 1249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Diplomat", description = "Ihr sagt, Elling hat Euch geschickt? Dann soll Euch meine Gastfreundschaft zehnfach zuteilwerden. Wenn Ihr etwas braucht, fragt nur. Ich tue mein Bestes, Euch zu unterstützen.\n\nHmm, Slim, sagt Ihr? Bei dem Namen klingelt nichts, aber ich werde nach ihm Ausschau halten.\n\nSchaut jetzt nicht hin, {name}, aber der Herr dort am Ausgang sieht herüber. Er folgt unserer Unterhaltung etwas zu intensiv, wenn Ihr versteht, was ich meine. Ich an Eurer Stelle würde tun, was ich kann, um ihn zu schnappen, bevor er zur Tür flieht.", sourceObjective = "Schnappt Tapoke Slim Jahn, bevor er entkommt, und kehrt dann zu Mikhail in Menethil zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1250] = { id = 1250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Diplomat", description = "Die Defias zahlten mir nicht genug, um für diese Sache zu sterben. Sie entführten den König. Ja, den König von Sturmwind, keinen kleinen Diplomaten. Er war auf dem Weg nach Theramore, um sich mit Jaina Prachtmeer zu treffen - offenbar eine große Sache und streng geheim. Aber es sind nicht nur die Defias darin verwickelt. Sie arbeiten mit jemandem zusammen. Ich glaube, sie wussten, dass das ihre Kräfte übersteigt.\n\nMeine Aufgabe war es, ihren Mann an Bord des königlichen Schiffes zu bringen, als es im Hafen lag. Der Typ hieß Hendel. Mehr weiß ich nicht. Ich schwöre es!", sourceObjective = "Sprecht mit Mikhail im Sumpfland.", sourceObjectiveStatus = "unverified-source-field" }
quests[1251] = { id = 1251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "he Black Shield" }
quests[1252] = { id = 1252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leutnant Paval Reethe", description = "Unter dem Geröll sticht Euch ein Funkeln ins Auge. Kaum sind Schmutz und Asche von dem Objekt gewischt, kommt das Emblem eines goldenen Ankers auf einer weißen Emailleoberfläche zum Vorschein: das Zeichen von Theramore.\n\nUnter dem Anker ist der Name \"Leutnant Paval Reethe\" eingeprägt.", sourceObjective = "Bringt Reethes Abzeichen zu Hauptmann Garran Mumm in Theramore.", sourceObjectiveStatus = "unverified-source-field" }
quests[1253] = { id = 1253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schwarze Schild", description = "Ein Eisenschild, vom Feuer geschwärzt, das in dem Gasthaus wütete, ist an dem verfallenen Kamin befestigt, einer der wenigen erhaltenen Teile des Gebäudes, das einmal das Gasthaus \"Zur Süßen Ruh\" war.\n\nDer Schild lässt sich von den Mauersteinen des Kamins ablösen.", sourceObjective = "Bringt den geschwärzten Eisenschild zu Hauptmann Garran Mumm in Theramore.", sourceObjectiveStatus = "unverified-source-field" }
quests[1258] = { id = 1258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "...und Käfer", description = "Eine weitere Komponente meines neuen Rezepts ist das gepanzerte Bein eines Riesenkrebses. Und die Krebse, die sie in den Düstermarschen haben - stachelige Steinkrabbe nennen sie sie -, sollten sich hervorragend eignen!\n\nDie Schale des Krebsbeins ist das wichtigste Element der Präsentation des Gerichts, daher brauche ich makellose, unverletzte Beine. Ein ausgewachsener Krebs hat möglicherweise nur ein oder zwei Beine, die in Frage kommen, aber ich brauche viel mehr für mein Gericht.\n\nMacht Euch auf den Weg zu den Felsen rund um Theramore und besorgt mir diese Beine.", sourceObjective = "Bringt 12 makellose Kriecherbeine zu Morgan Stern in Theramore.", progress = "Meine Experimente mit den Schlammpanzerzungen machen gute Fortschritte. Ich hoffe, Eure Krebssuche kommt voran?", completion = "Das sind wunderbare Exemplare, {name}! Die Schalen sind in perfektem Zustand, das Fleisch ist rosa und zart. Ich bin sicher, das Blut eines Küchenchefs fließt in Euren Adern!", sourceObjectiveStatus = "unverified-source-field" }
quests[1259] = { id = 1259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leutnant Paval Reethe", description = "Ich kenne den Namen Leutnant Paval Reethe nicht. Am besten erkundigt Ihr Euch bei Adjutant Tesoran. Er hat alle Aufzeichnungen über die Wachen von Theramore, vom Personal bis hin zur Ausrüstung.\n\nEr sollte Euch nach einem Blick in seine Bücher sagen können, wer dieser Reethe ist.", sourceObjective = "Findet bei Adjudant Tesoran in Theramore mehr über Reethe heraus.", sourceObjectiveStatus = "unverified-source-field" }
quests[1260] = { id = 1260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgan Stern", description = "Ich entwickle ein neues Menü für das Restaurant. Es soll aus regionalen Gerichten mit einem Hauch von \"Bayou\" bestehen. Ich glaube, meine Kunden im Blauen Eremiten werden es lieben!\n\nIch schickte meinen Neffen Morgan nach Theramore, einer Stadt am Rand der Düstermarschen. Er sammelt die Rezepte der Einheimischen und ich muss wissen, was er bisher gefunden hat.\n\nDie Reise nach Theramore ist lang. Zu lang für mich. Aber ich wette, <ein/eine:c> {class} wie Ihr <einer/eine:c> seid, nutzt jede Chance für eine Reise, ja?", sourceObjective = "Sprecht mit Morgan Stern in Theramore.", sourceObjectiveStatus = "unverified-source-field" }
quests[1261] = { id = 1261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marg spricht", description = "Verfluchter Matschpanzer! Man kann Marg nicht töten! Ah, aber ich bin tot. Also muss er mich getötet haben...\n\nAber meine Mission! Meine Mission! Ihr, {name}, müsst sie beenden.\n\nIn der Nähe von Theramore sah ich eine Gruppe Soldaten der Allianz am Ufer kampieren. Ein Soldat trug einen Anhänger... einen Anhänger mit mehr Edelsteinen, als ihn sich ein Soldat leisten könnte!\n\nIn jener Nacht schlich ich in ihr Lager und stahl den Anhänger, aber nach meiner Rückkehr zum Stützpunkt tötete mich ein Matschpanzerkrebsmann!\n\n{name}, Ihr müsst diesen Matschpanzer finden und den Anhänger retten!", sourceObjective = "Bringt den juwelenbesetzten Anhänger zu Nazeer in Brackenwall.", sourceObjectiveStatus = "unverified-source-field" }
quests[1262] = { id = 1262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bei Zor melden", description = "Wie seltsam, dass sich der Anhänger, den Marg stahl, in den Händen eines gemeinen Soldaten befand. Vielleicht hatte sich sein Besitzer verkleidet, oder die Soldaten selbst hatten ihn gestohlen!\n\nWas auch immer, dies ist der Anhänger eines Adligen und wir müssen seinen wahren Besitzer finden, wenn wir das Rätsel lösen wollen.\n\nBringt den Anhänger zu Zor Einbaum in Orgrimmar. Er ist mit der Politik der Allianz vertraut und wird wissen, ob dieser Anhänger etwas mit der Geschichte der Adligen von Sturmwind zu tun hat.", sourceObjective = "Bringt den Edelsteinanhänger zu Zor Einbaum in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[1263] = { id = 1263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das brennende Gasthaus <ZU TRATSCH WECHSELN>" }
quests[1264] = { id = 1264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Diplomat", description = "Am Anfang jedes Monats werden die Marinesoldaten von Kul Tiras bezahlt und verlassen Theramore meist mit anderen Zielen. Viele kommen hierher, um Frauen aufzureißen, zu zechen und ihren Spaß zu haben. Eine dieser Gruppen betrachte ich als Stammgäste der Taverne, und ich glaube, dieser Hendel ist dabei.\n\nKommandant Samaul in Theramore könnte Euch helfen, ihn zu finden, wenn Hendel noch hier stationiert ist. Er ist Prachtmeer treu ergeben, aber wenn Ihr Ellings Namen erwähnt, dürfte er Euch helfen... diskret.", sourceObjective = "Sucht Kommandant Samaul in den Düstermarschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1265] = { id = 1265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Diplomat", description = "Hendel? Ja, ich kenne den Mann. Aber wozu braucht Ihr einen meiner Soldaten?\n\nHat Elling Euch geschickt, ihn zu finden? Hmm, das gefällt mir ganz und gar nicht. Elling hätte Euch nicht zuerst zu mir geschickt, wenn Euer Anliegen nicht beunruhigend wäre. Ich verstehe, wenn Ihr mir nicht sagen könnt, worum es geht, aber denkt daran: Ich muss dieses Land beschützen. Wenn Ihr vorhabt, die Ruhe zu stören, solltet Ihr mich so viel wie möglich wissen lassen.\n\nIch glaube, Hendel war im ersten Turm außerhalb von Theramore stationiert. Seid vorsichtig.", sourceObjective = "Sucht die Späherwacht nach Spuren des Gefreiten Hendel ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[1266] = { id = 1266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Diplomat", description = "Der Gefreite Hendel hält sich westlich von hier auf. Im Augenblick ist er auf Wache und beschützt einige von Theramores Spitzeln, während sie ausruhen. Sie behalten Brackenwall, den Stützpunkt der Horde, im Auge und suchen nach allem, das unsere Grenzen bedrohen könnte.\n\nIhr müsstet ihn problemlos finden können; sucht einfach nach Zelten am Straßenrand.\n\nIch muss mich um andere Dinge kümmern, stoße aber bestimmt bald zu Euch. Ihr könnt mich immer im Turm von Lady Prachtmeer in Theramore finden, falls Ihr Probleme habt.", sourceObjective = "Sucht den Gefreiten Hendel in den Düstermarschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1267] = { id = 1267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Diplomat", sourceObjective = "Sprecht mit Jaina Prachtmeer im Sumpf der Düstermarschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1268] = { id = 1268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "uspicious Hoofprints" }
quests[1269] = { id = 1269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ieutenant Paval Reethe" }
quests[1270] = { id = 1270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stinkis Flucht", description = "Klasse, endlich etwas, das mich nicht essen will!!!\n\nIch brauche Hilfe mit den Tierwesen hier, und Ihr kommt gerade recht, <Jungchen/Mädel>.\n\nEin Goblin aus Ratschet namens Mebok Mizzyrix braucht ein paar Sumpfbohnenblätter für einen Trank oder so... Mir ist ganz ehrlich einerlei, warum - er hat gut bezahlt und ich kenne diesen Sumpf, also bin ich hier.\n\nZu dumm, dass ich umzingelt wurde, bevor ich die Sumpfbohnen fand! Könnt Ihr mir hier raushelfen und auf mich aufpassen, während ich nach Meboks Pflanze suche?", sourceObjective = "Begleitet \"Stinki\" Ignatz und sprecht dann mit Mebok Mizzyrix in Ratschet.", completion = "Stinki war mit den Kräutern hier, die ich wollte, und sagte mir, Ihr habt ihn aus einer misslichen Lage befreit. Gute Arbeit! Ein Freund von Stinki ist ein Freund von mir!\n\nEr bat mich, Euch das zu geben, wenn ich Euch sehen sollte, bevor er wieder nach Süden in die Sümpfe ging.", sourceObjectiveStatus = "unverified-source-field" }
quests[1271] = { id = 1271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Festmahl im Blauen Eremiten", sourceObjective = "Mein Neffe sagte, Ihr habt ihn bei seiner Suche in den Düstermarschen unterstützt und seinem Assistenten aus der Klemme geholfen. Also wir Sterns halten zusammen und vergessen unsere Freunde nicht!\n\nAlso wascht Eure Hände, {name}, denn wir geben Euch zu Ehren eine Party!", sourceObjectiveStatus = "unverified-source-field" }
quests[1272] = { id = 1272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht Reethe <ZU TRATSCH WECHSELN>" }
quests[1273] = { id = 1273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befragt Reethe", description = "Es hat lange gedauert, aber ich fand Reethe. Für einen Menschen hatte er sich gut versteckt.\n\nOgron hatte Angst, nach der langen Zeit im Sumpf könnte er verrückt sein. Ihr kommt mit mir, denn wir brauchen Antworten von ihm.", sourceObjective = "Geht mit Ogron und sprecht mit Reethe, dann kehrt zu Krog in Brackenwall zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1274] = { id = 1274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Diplomat", description = "Pardon, <werter Herr/holde Dame>. Bischof DeLavey bat mich, Abenteurer zu suchen, die ihm in einer delikaten Angelegenheit helfen könnten.\n\nWenn Ihr so gut sein könntet, heimlich zur Burg Sturmwind zu reiten und mit ihm zu sprechen, sobald es Euch genehm ist - er wäre Euch sicherlich für Eure Hilfe dankbar. Und nochmals, bitte seid diskret. Es ist eine wichtige Angelegenheit.", sourceObjective = "Sucht Bischof DeLavey in der Burg Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[1275] = { id = 1275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erforschung der Verderbnis", description = "Törichte Blutelfen spielen mit Dämonenmagie. Wurden sie nicht Zeugen, was mit den Naga und den Satyrn von Kalimdor geschehen ist?\n\nIch fürchte, die Blutelfen werden auf ähnliche Weise deformiert. Azeroth darf kein weiteres Volk abscheulicher Monster hervorbringen.\n\nIch möchte die Hirnstämme der Satyrn und Naga untersuchen, damit ich daraus folgern kann, welches Schicksal die Elfen erwartet. In der Tiefschwarzen Grotte unweit von hier im Westen werdet Ihr sowohl Satyrn als auch Naga finden.", sourceObjective = "Relwyn Schattenstern am Stützpunkt an der Grotte benötigt 8 verderbte Gehinstämme.", sourceObjectiveStatus = "unverified-source-field" }
quests[1276] = { id = 1276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schwarze Schild", description = "Ah, jetzt erinnere ich mich! Mosarn ist ein angesehener Schmied in Donnerfels. Ich wusste, ich habe den Namen schon einmal gehört.\n\nAls Dank belohnte mich der Irdene Ring mit einem von Mosarn hergestellten Satz Rüstungen. Sehr gute Arbeit.\n\nVielleicht kann er Euch mehr über den Schild sagen, den er anfertigte.\n\nEs ist nicht viel, aber da wir aus Reethe nichts Nützliches herausbekamen, bleibt uns wohl nichts anderes übrig.", sourceObjective = "Bringt den geschwärzten Eisenschild zu Mosarn in Donnerfels.", sourceObjectiveStatus = "unverified-source-field" }
quests[1281] = { id = 1281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jims Lied <ZU TRATSCH WECHSELN>" }
quests[1282] = { id = 1282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie nennen ihn den lächelnden Jim", description = "Ich kann nicht anders, der alte Jim da tut mir leid. Er war nicht immer so. Hatte eine Zeitlang ein Gasthaus im Sumpf, wunderbares Lokal.\n\nHört zu, ich will wirklich nicht darüber sprechen. Besprecht es mit Hauptmann Mumm, wenn es sein muss. Ihr findet ihn auf der obersten Etage der Wehrzitadelle, der großen Kaserne östlich von Lady Jainas Turm.", sourceObjective = "Sprecht mit Hauptmann Garran Mumm auf der obersten Etage der Wehrzitadelle in Theramore.", sourceObjectiveStatus = "unverified-source-field" }
quests[1283] = { id = 1283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuer im Gasthaus \"Zur Süßen Ruh\" <ZU TRATSCH WECHSELN>" }
quests[1284] = { id = 1284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdächtige Hufabdrücke", description = "Reihen von Hufspuren führen von den noch rauchenden Überresten des Gasthauses \"Zur Süßen Ruh\" weg. Wenigstens einige Abdrücke sind klar erkennbar, weitere Reihen sind im weichen Schlamm des Sumpfs kaum zu sehen.", sourceObjective = "Berichtet Hauptmann Garran Mumm in Theramore von den verdächtigen Abdrücken beim Gasthaus \"Zur Süßen Ruh\".", sourceObjectiveStatus = "unverified-source-field" }
quests[1285] = { id = 1285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daelins Männer", description = "Reddon... Oh, da haben wir ihn! Leutnant Paval Reethe.\n\nTrat den Wachen von Theramore zusammen mit den meisten Rekruten bei, die mit Lady Prachtmeer über das Meer kamen. Trat mit sechzehn Jahren den Marinesoldaten von Kul Tiras bei. Herausragende Dienste, Beförderungen...\n\nIst als vermisst eingetragen.", sourceObjective = "Kehrt mit den Informationen über Reethe zu Hauptmann Garran Mumm in Theramore zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1286] = { id = 1286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Deserteure", description = "Es war ein ständiger Kampf, in den Marschen präsent zu bleiben, aber durch die Kraft unserer Entschlossenheit konnten wir mehrere Wachtürme in diesem Gebiet zur Verteidigung halten.\n\nDie aktuellsten Informationen und Späherberichte, die ich bekam, deuten darauf hin, dass eine Gruppe Deserteure sich in unserem alten Turm bei der Verlassenen Wacht, südöstlich des Gasthauses, eingenistet hat.\n\nDer örtliche Anführer der Deserteure ist ein Mann namens Balos Jacken. Seht zu, ob Ihr Informationen über ihn bekommt.\n\nSeid gewarnt, {name}. Er könnte sich als harte Nuss erweisen.", sourceObjective = "Sammelt Informationen über Reethe von Balos Jacken und den Deserteuren in den Düstermarschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1287] = { id = 1287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Deserteure", description = "Reethe? Dieser Feigling?\n\nWir warfen ihn aus dem Lager hinaus, weil er dauernd die Vorräte der Oger in Brackenwall plündern wollte. So viele sind wir nicht, dass wir es mit diesen hirnlosen Schlägern aufnehmen könnten.\n\nEr hat das Fass zum Überlaufen gebracht, daher haben wir ihn sich selbst überlassen.\n\nAlso ich habe Euch geholfen... Warum helft Ihr jetzt nicht uns und vergesst, dass Ihr uns gefunden habt?", sourceObjective = "Sprecht mit Hauptmann Garran Mumm in Theramore über Reethe.", sourceObjectiveStatus = "unverified-source-field" }
quests[1288] = { id = 1288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mumms Bericht", description = "Ihr habt gute Arbeit geleistet, {name}, die Beste, die ich je von einem Amateur sah.\n\nLady Prachtmeer bat mich, sie über diese delikate Situation auf dem Laufenden zu halten, aber ich habe eine Weile nicht mit ihr gesprochen.\n\nIch wollte ihr meinen Bericht später bringen, aber es scheint mir passender, wenn Ihr mit ihr darüber sprecht. Ihr könnt ihre Fragen wahrscheinlich besser beantworten als ich.", sourceObjective = "Bringt Mumms Bericht zu Lady Jaina Prachtmeer in Theramore.", sourceObjectiveStatus = "unverified-source-field" }
quests[1301] = { id = 1301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "James Hyal", description = "Bevor ich hier im Blauen Eremiten arbeitete, wurde ich von einem der besten Küchenchefs und Gastwirte ausgebildet, die ich kenne. Sein Name war James Hyal. Alles, was ich besitze und im Leben erreicht habe, verdanke ich ihm.\n\nIch frage mich, was er wohl so treibt... Sein Bruder Vincent und er wollten in einer Taverne im Hafen von Menethil arbeiten, aber ich habe lange nichts von ihm gehört.\n\nWenn Ihr jemals in diese Gegend kommen solltet, könntet Ihr ihm dann Grüße von mir bestellen?", sourceObjective = "Sprecht mit Vincent Hyal im Hafen von Menethil.", sourceObjectiveStatus = "unverified-source-field" }
quests[1302] = { id = 1302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "James Hyal", description = "Mein Bruder James fuhr mit Lady Prachtmeer über das Meer. Als Letztes hörte ich, dass die Kämpfe dort drüben beigelegt waren und James irgendwo auf dem Kontinent ein Gasthaus eröffnete. Wo immer er sein mag, ich bin sicher, seine Geschäfte blühen. Er war ein verdammt guter Koch.\n\nAber ich habe eine Weile nichts mehr von ihm gehört - zu sehr mit seinem Gasthaus beschäftigt, denke ich. Der Amtmann in Theramore könnte Euch vielleicht zu ihm führen. Sucht ihn auf der obersten Etage dieser Zitadelle, die in der Mitte der Stadt steht. Ich glaube, sie nennen sie die Wehrzitadelle.", sourceObjective = "Sprecht mit Amtmann Lendry bei der Wehrzitadelle in Theramore.", sourceObjectiveStatus = "unverified-source-field" }
quests[1318] = { id = 1318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die offene Rechnung der Gordok", description = "Nun Ihr de' König sein, vielleicht Ihr kriegen zurück wertvolles Artefakt der Gordok von gruseligen Elf, der sich selbst nennen Prinz! König vor Euch hat versagt, so wie alle Könige seit Tortheldrin - de' gruselige Elf - es gestohlen hat, von damaligen Gordokkönig!\n\nArtefakt heißen Stulpen der Gordokmacht. Alte Zeit Geschichten sagen, nur wahre König de' Gordok kann sie zurückholen. Alte Zeit Geschichten sagen auch, der gruselige Elf ist immer noch hier - Ihr finden es und es werden Eure mächtigen Stulpen, für immer! Yar, ich zeigen!", sourceObjective = "Findet die Stulpen der Gordokmacht und bringt sie zu Hauptmann Krombruch in Düsterbruch.\n\nKrombruch zufolge sagen die \"Alte Zeit Geschichten\", dass Tortheldrin - ein \"gruseliger\" Elf, der sich selbst als Prinz bezeichnet- sie einem der Gordokkönige gestohlen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[1319] = { id = 1319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schwarze Schild", description = "Ich kann Euch leider nicht weiterhelfen, {name}, schicke Euch aber zu jemandem, der es kann. Caz Doppelspross, einer unserer besten Schmiede, arbeitet in der Schmiede.\n\nBringt ihm den Schild und hört Euch an, was er zu sagen hat.", sourceObjective = "Zeigt den geschwärzten Eisenschild Caz Doppelspross in Theramore.", sourceObjectiveStatus = "unverified-source-field" }
quests[1320] = { id = 1320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schwarze Schild", description = "Ah, das hätte ich fast übersehen... Der Ledergurt an der Rückseite muss verbrannt sein, aber er war offenbar für eine große Person gemacht. Ich schätze, für einen Tauren.\n\nMehr kann ich Euch nicht sagen. Sagt Hauptmann Mumm, es tut mir leid, dass ich nicht mehr helfen konnte.", sourceObjective = "Sprecht mit Hauptmann Garran Mumm in Theramore.", sourceObjectiveStatus = "unverified-source-field" }
quests[1321] = { id = 1321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schwarze Schild", description = "Hmm... Ich sehe nichts Ungewöhnliches an diesem Schild. Do'gol, der Schmied, sollte ihn sich ansehen. Vielleicht kann er uns mehr sagen, aber große Hoffnungen würde ich mir nicht machen...", sourceObjective = "Zeigt den geschwärzten Eisenschild Do'gol in Brackenwall.", sourceObjectiveStatus = "unverified-source-field" }
quests[1322] = { id = 1322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schwarze Schild", description = "Hmmm, hier am Rand des Schildes steht etwas geschrieben, aber durch die Brandspuren kann man es kaum lesen.\n\nIch brauche Säure, um ihn zu reinigen. Das Gift der Graunebelspinnen sollte dafür ausreichen. Die Spinnen haben sich in einer alten Mine in den Graunebelhöhlen nordwestlich der Siedlung eingenistet. Bringt mir ihre Giftsäcke und ich reinige diesen Schild.", sourceObjective = "Bringt 5 säurehaltige Giftbeutel zu Do'gol in Brackenwall.", sourceObjectiveStatus = "unverified-source-field" }
quests[1323] = { id = 1323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schwarze Schild", description = "Oh, ich glaube, ich habe zu viel Säure auf den Schild geschüttet. Lasst mich ein wenig rubbeln...\n\nHm, schwer zu lesen, sieht aber wie der Name Mosarn aus. Nie von ihm gehört. Vielleicht weiß Krog etwas. Krog kennt viele Leute.", sourceObjective = "Sprecht mit Krog in Brackenwall.", sourceObjectiveStatus = "unverified-source-field" }
quests[1324] = { id = 1324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Diplomat", description = "Was?! Ihr kommt hierher und werft mir vor, ich mache mit den Defias gemeinsame Sache und glaubt, ich höre mir diese Beleidigungen an? Etwas sagt mir, dass Ihr das schon lange verdient habt.", sourceObjective = "Besiegt den Gefreiten Hendel in den Düstermarschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1338] = { id = 1338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmlanzes Bestellung", description = "Es gibt einen Rüstungsschmied bei den Zwergen, dessen Arbeit ich sehr bewundere. Sein Name ist Furen Langbart und seine Fertigkeit unübertroffen. Ich brauche einen neuen Schild und muss einen von ihm haben!\n\nDas Problem ist... Furen lebt weit im Süden im Zwergendistrikt von Sturmwind. Im Menschenland! Ich kann mir nicht vorstellen, warum er dort lebt, so weit weg von Eisenschmiede. Die Menschen müssen ihn fürstlich bezahlen, damit er dort bleibt!\n\nWenn Ihr reisen wollt und nichts gegen das Geldverdienen habt, würdet Ihr Furen dann meine Bitte nach einem Schild überbringen?", sourceObjective = "Bringt Sturmlanzes Anforderung zu Furen Langbart in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[1339] = { id = 1339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebirgsjäger Sturmlanzes Aufgabe", description = "Ich hörte, Gebirgsjäger Sturmlanze sucht nach einem Läufer. Jemand, der eine Reise für ihn unternimmt. Wie wäre es? Seid Ihr <ein/eine:r> {race}, <der/die:r> für den Job geeignet ist?\n\nWenn ja, findet Ihr Sturmlanze auf der Spitze des nördlichen Wachturms.", sourceObjective = "Sprecht mit Gebirgsjäger Sturmlanze.", sourceObjectiveStatus = "unverified-source-field" }
quests[1358] = { id = 1358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Probe für Helbrim", description = "Ein Kollege in Kalimdor, Apotheker Helbrim, untersucht die Auswirkungen von Lordaerons Toxinen auf die Wildtiere von Kalimdor. Er wäre an einer Probe der Wolfherzen interessiert, die Renferrel mir geschickt hat.\n\nHelbrim lebt im Brachland in einem Dorf am Wegekreuz. Um ihn zu erreichen, müsst Ihr per Zeppelin zur Hauptstadt der Orcs, Orgrimmar, reisen und dann zu Fuß Richtung Süden nach Durotar. Geht durch das Brachland nach Westen und Ihr erreicht bald die Siedlung am Wegekreuz.", sourceObjective = "Bringt die Wolfherzprobe zu Apotheker Helbrim ins Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[1359] = { id = 1359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zinges Lieferung", description = "Die Wolfherzen, die Ihr beschafft habt, verfügen über ein Merkmal, das es in ähnlichen Proben nicht gibt. Sie verfügen über eine Giftigkeit, die für genau die Wölfe tödlich sein müsste, in denen die Herzen schlagen!\n\nEs ist unglaublich und wir müssen das weiter untersuchen. Ich habe einige Proben der gewonnenen Herzen aufbewahrt. Bringt sie zu meiner Kollegin, Apothekerin Zinge. Ihr findet sie in unserem Hauptquartier in Unterstadt.", sourceObjective = "Bringt die Wolfherzproben zu Apothekerin Zinge nach Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1360] = { id = 1360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederbeschaffte Schätze", description = "Ich hatte selbst eine gute Arbeitsstelle als Buddler an der Uldaman-Ausgrabungsstätte im Ödland... das heißt, bis diese verfluchten Troggs auftauchten. Ich konnte gerade noch mit heiler Haut entkommen, das war alles. In dem Chaos habe ich meinen wertvollsten Besitz zurückgelassen. Natürlich ist er in meiner Truhe sicher vor den Troggs, aber die befindet sich mitten unter ihnen.\n\nIch wäre in Eurer Schuld, sowohl in Ehre als auch in Münze, wenn Ihr sie für mich besorgen könntet! Eine Truhe mit meinem Namen darauf befindet sich am Ende der Nördlichen Bankenhalle. Dorthin müsst Ihr gelangen.", sourceObjective = "Holt Krom Starkarms wertvollen Besitz aus seiner Truhe in der Nördlichen Bankenhalle von Uldaman und bringt den Schatz zu ihm nach Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[1361] = { id = 1361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Regthar Totenfurt", description = "Ein Krieger der Horde, Regthar Totenfurt, rekrutiert Agenten für einen Einsatz im Land Desolace. Sprecht mit ihm, wenn Ihr Euch freiwillig melden wollt. Er lebt im Brachland in einer Reihe von Bunkern westlich des Wegekreuzes.\n\nUnd schärft Eure Waffen. Desolace ist ein vom Krieg zerrissener Ort.", sourceObjective = "Sprecht mit Regthar Totenfurt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1362] = { id = 1362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kolkar von Desolace", description = "Die Kolkarzentauren leben in Desolace. Ihre Truppen sind in das Brachland vorgestoßen. Das ist bekannt. Agenten der Horde kümmern sich dort um sie.\n\nAber so lange die Zentauren in Desolace so stark sind, werden sie immer eine Bedrohung sein. Es wird Zeit, dass wir uns diese Bedrohung vom Hals schaffen.\n\nSprecht mit Felgur Zweischneid beim Geistwandlerposten in Desolace. Seine Aufgabe war es, Informationen über die Zentauren zu sammeln. Er weiß bestimmt, wie man am besten mit den Kolkar von Desolace fertig wird.", sourceObjective = "Sprecht mit Felgur Zweischneid beim Geistwandlerposten in Desolace.", sourceObjectiveStatus = "unverified-source-field" }
quests[1363] = { id = 1363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mazens Befehl", description = "Als Verwalter der Arbeit hier in der Bibliothek der Akademie der Arkanen Künste und Wissenschaften liegt es in meiner Verantwortung, dafür zu sorgen, dass alle magischen Folianten und Rollen stets erfasst sind. Wer weiß, was Schlimmes geschehen würde, fielen einige dieser verzauberten Texte in die falschen Hände?\n\nDabei fällt mir ein...mein Assistent Dellis machte letzte Woche einen schrecklichen Fehler. In der Bibliothek ist er recht tüchtig, aber inkompetent, wenn er die Tore von Sturmwind hinter sich lässt. Seid ein Held und helft dem alten Dellis, ja?", sourceObjective = "Sprecht mit Akolyth Dellis in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[1364] = { id = 1364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mazens Befehl", description = "Meister Mazens Anweisungen waren ganz klar: Bringt einen sehr wichtigen Essay zu Behüter Mahar Ba in der Burg Nethergarde.\n\nAber ich bin noch nie in den Verwüsteten Landen gewesen. Die Reise war beängstigend!\n\nAls ich an die Sümpfe des Elends kam, bog ich falsch ab und war plötzlich von grässlichen pflanzenartigen Sumpfwesen umzingelt. Sie schienen mich angreifen zu wollen, also lief ich weg. Doch in meiner Hast ließ ich den Essay fallen. Ich bin sicher, eine der Bestien hat ihn genommen.\n\nKönntet Ihr bitte versuchen, ihn zu holen und zu Mahar Ba zu bringen?", sourceObjective = "Rettet Khadgars 'Abhandlungen über dimensionale Konvergenz' und bringt sie zu Behüter Mahar Ba in der Burg Nethergarde.", sourceObjectiveStatus = "unverified-source-field" }
quests[1365] = { id = 1365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khan Dez'hepah", description = "Die Kolkar sind nicht die einzigen Zentauren von Desolace. Viele Klans ziehen durch diese trockenen Ebenen, bekämpfen einander und sterben. Und es ist gut, dass sie sich untereinander bekämpfen, denn sie sind stark und brutal. Vereinten sich die Zentauren gegen uns, wären sie ein schrecklicher Gegner.\n\nWir müssen sie erledigen, bevor sie sich zusammentun.\n\nEuer erster Schritt ist, den Kolkarklan zu schwächen. Macht das, indem Ihr den Anführer Khan Dez'hepah besiegt.\n\nDas Dorf Kolkar liegt nordöstlich von hier. Geht, und möge Euch das Glück hold sein.", sourceObjective = "Bringt Khan Dez'hepahs Kopf zu Felgur Zweischneid in Desolace.", sourceObjectiveStatus = "unverified-source-field" }
quests[1366] = { id = 1366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zentaurenkopfgeld", description = "Da Ihr die Zentaurenklans jetzt eingeschüchtert habt, wird es Zeit, sie bluten zu lassen. Wenn Ihr durch Desolace reist, jagt Zentauren. Mir ist gleich, welchen Klan Ihr jagt. Sammelt nur Ohren. Bergeweise Ohren.\n\nWenn Ihr ihre Zahl dezimiert, schwächt Ihr ihre Entschlossenheit und macht alle Gedanken an Expansion zunichte.\n\nGute Jagd, {name}.", sourceObjective = "Bringt 15 Zentaurenohren zu Felgur Zweischneid in Desolace.", sourceObjectiveStatus = "unverified-source-field" }
quests[1367] = { id = 1367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allianz mit den Magram", description = "Um die Zentauren zu schlagen, müssen wir ihren Hass gegen sie wenden. Wir verbünden uns mit einem Klan und lernen durch ihn, wie wir alle Klans besiegen können.\n\nWenn Ihr Euch mit den Magram verbünden wollt, dann tötet ihre Gegner, die Gelkis. Das wird Euch den Respekt der Magram einbringen. Wenn Ihr genug verdient habt, dann trefft Euch mit dem Sprecher der Magram Warug am Rand des Dorfes Magram im Südosten von Desolace.", sourceObjective = "Baut Euch einen freundlichen Ruf bei den Magram auf und sprecht dann mit Warug.", sourceObjectiveStatus = "unverified-source-field" }
quests[1368] = { id = 1368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allianz mit den Gelkis", description = "Um die Zentauren zu schlagen, müssen wir ihren Hass gegen sie wenden. Wir verbünden uns mit einem Klan und lernen durch ihn, wie wir alle Klans besiegen können.\n\nWenn Ihr Euch mit den Gelkis verbünden wollt, dann tötet ihre Gegner, die Magram. Wenn Ihr Euch den Respekt der Gelkis verdient habt, dann trefft Euch mit der Schamanin der Gelkis, Uthek der Weisen, am Rand des Dorfs der Gelkis im Südwesten von Desolace.", sourceObjective = "Baut Euch einen freundlichen Ruf bei den Gelkis auf und sprecht dann mit Uthek der Weisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1369] = { id = 1369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerbrochene Tränen", description = "Die Gelkis glauben, dass unsere Zentaurenmutter Theradras uns beschützt. Sie sind dumm. Niemand beschützt die Zentauren. Die Magram brauchen keinen Schutz! Wir sind die Stärksten!\n\nZeigt den Gelkis, dass sie dumm sind. Geht zu der Höhle in ihrem Dorf. Sie horten Kristalle in dieser Höhle, die Tränen von Theradras. Zerstört die Tränen und bringt mir die zerbrochenen Stücke!", sourceObjective = "Wahrt Euren Ruf bei den Magram und bringt 3 zerbrochene Tränen zu Warug im Dorf Magram.", sourceObjectiveStatus = "unverified-source-field" }
quests[1370] = { id = 1370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diebstahl von Vorräten", description = "Wenn wir nicht im Krieg sind, jagen wir wegen Fleisch. Fleisch gibt uns Kraft und volle Bäuche kämpfen besser als leere.\n\nSo ist es bei den Magram. Sie lagern überschüssiges Fleisch ein, damit sie zwischen den Jagdausflügen länger kämpfen können. Wenn man ihr Dorf im Osten überfällt und ihre Fleischvorräte raubt, wird ihre Kraft schwinden.", sourceObjective = "Bringt 6 Taschen primitiv getrocknetes Fleisch zu Uthek der Weisen im Dorf der Gelkis.", sourceObjectiveStatus = "unverified-source-field" }
quests[1371] = { id = 1371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gizmo für Warug", description = "Vor langer Zeit kam ein kleiner Gnom nach Desolace. Er hatte Pferde und einen Karren, und auf dem Karren viele seltsame Dinge. Komische Dinge. Dinge, die in verschiedenen Farben brannten. Dinge, die sich bewegten und doch nicht lebten. Ich tötete den kleinen Gnom, aber vorher...brachte er mich zum Lachen.\n\nIch behielt mein liebstes Ding von dem Wagen. Es war ein Mensch aus Holz, der mir zuwinkte, bis ich ihn schlug und zerbrach.\n\nIch will einen Neuen. Besorgt mir einen Neuen!", sourceObjective = "Wahrt Euren Ruf bei den Magram und bringt eine hochentwickelte Zielattrappe zu Warug im Dorf Magram in Desolace.", sourceObjectiveStatus = "unverified-source-field" }
quests[1372] = { id = 1372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichts als die Wahrheit", description = "Auf Befehl von Varimathras wurde unsere Expeditionsstreitmacht ausgeschickt, um das untere Azeroth zu vermessen.\n\nBeim Spähen bemerkte ich einen Spitzel der Menschen, der den Bettlerschlupfwinkel ausspionierte. Ehe ich ihn festnehmen konnte, schnappten ihn einige unserer...Orcbrüder...und brachten ihn nach Steinard, ihrer Festung in den Sümpfen des Elends.\n\nIch möchte unseren Orcverbündeten...helfen. Sie sahen unser Lager hier nicht, dennoch wollte ich sie unterstützen.\n\nIch arbeitete hier mit Faustin, um ein...Wahrheitsserum für unseren Freund in Steinard zu entwickeln.", sourceObjective = "Sprecht mit Apotheker Faustin im Bettlerschlupfwinkel.", sourceObjectiveStatus = "unverified-source-field" }
quests[1373] = { id = 1373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ongeku", description = "Ihr müsst noch mehr beweisen und Eure nächste Aufgabe führt Euch weit weg, daher werden die Gelkis die Magram vorerst ohne Euch bekämpfen.\n\nDie Erde flüstert jenen, die zuhören, viele Geheimnisse zu. Ein Geheimnis, von dem ich höre, betrifft einen roten Kristall. Er heißt Draenethyst und ist neu auf unserer Erde. Er stammt von einem Ort, wo Berge fliegen und Dämonen herrschen.\n\nBringt mir einen Splitter Draenethyst; er macht meine Magie stark! Der Splitter befindet sich an einem Ort namens Sümpfe des Elends und ist im Besitz von Ongeku, dem Verirrten.", sourceObjective = "Wahrt Euren Ruf bei den Gelkis und bringt einen Draenethystsplitter zu Uthek der Weisen im Dorf der Gelkis in Desolace.", sourceObjectiveStatus = "unverified-source-field" }
quests[1374] = { id = 1374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khan Jehn", description = "Die Erde spricht zu mir und sagt, dass die Magram schwach werden. Jetzt ist es Zeit, ihren Khan zu töten!\n\nBringt mir den Kopf des Magramkahns Jehn!", sourceObjective = "Bringt Khan Jehns Kopf zu Uthek der Weisen im Dorf der Gelkis in Desolace.", sourceObjectiveStatus = "unverified-source-field" }
quests[1375] = { id = 1375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khan Shaka", description = "Ihr helft den Magram und ich mag Euch. Tötet jetzt den Khan der Gelkis! Er ist Khan Shaka und ich will seinen Kopf! Ich möchte seinen Kopf ansehen und ihn auslachen!", sourceObjective = "Wahrt Euren Ruf bei den Magram und bringt den Kopf von Khan Shaka zu Warug im Dorf Magram in Desolace.", sourceObjectiveStatus = "unverified-source-field" }
quests[1380] = { id = 1380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khan Hratha", description = "{name}, Ihr habt uns gegen die Magram geholfen. Jetzt helft uns dabei, die Maraudine zu schlagen! Tötet den Anführer ihres Klans, Khan Hratha!\n\nUm ihn herauszufordern, blast das Kriegshorn der Maraudine. Es befindet sich auf einem hohen Steilhang im Tal der Speere.\n\nDoch um das Horn zu blasen, müsst Ihr erst ein Kriegshornmundstück finden. Diese Teile sind selten und sind ausschließlich im Besitz der vertrauenswürdigsten Maraudinezentauren.\n\nNachdem das Horn geblasen wurde, werden Zentauren kommen. Tötet sie, bis Hratha auftaucht.\n\nKhan Hratha besitzt ein Stück eines... Schlüssels. Bringt es mir...", sourceObjective = "Wahrt Euren Ruf bei den Gelkis und bringt das Schlüsselfragment der Maraudine zu Uthek der Weisen im Dorf der Gelkis.", sourceObjectiveStatus = "unverified-source-field" }
quests[1381] = { id = 1381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khan Hratha", description = "Der Khan der Gelkis ist tot, und jetzt werden die Maraudine fallen! Tötet Hratha, den Khan der Maraudine!\n\nUm ihn herauszufordern, blast das Horn auf dem hohen Steilhang im Tal der Speere. Doch um das Horn zu blasen, braucht Ihr erst ein Kriegshornmundstück. Um ein Mundstück zu finden, müsst Ihr Zentauren der Maraudine töten. Tötet sie so lange, bis Ihr ein Mundstück habt. Dann blast das Horn.\n\nTut dies, und Zentauren der Maraudine werden zum Turm kommen. Tötet sie, bis Khan Hratha auftaucht. Khan Hratha besitzt ein Stück eines Schlüssels. Gebt mir dieses Stück...", sourceObjective = "Wahrt Euren Ruf bei den Magram und bringt das Schlüsselfragment der Maraudine zu Warug im Dorf Magram in Desolace.", sourceObjectiveStatus = "unverified-source-field" }
quests[1382] = { id = 1382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seltsame Allianz", description = "Wir können von Glück reden, dass die Zentauren sich untereinander bekämpfen, denn als vereinigte Kraft könnte sie nichts aufhalten. Ja, das kommt uns zugute und wir sollten unseren Vorteil ausbauen.\n\nEiner der Zentaurenklans, der Gelkisklan, führt einen brutalen Krieg gegen den Magramklan. Wenn wir die Magram angreifen, können wir vielleicht eine Allianz mit den Gelkis schmieden.\n\nSprecht mit Uthek der Weisen im Randbezirk der Gelkislager im Südwesten von Desolace. Durch sie könnten wir eine Allianz mit den Gelkis schmieden.", sourceObjective = "Baut eine freundliche Beziehung zu den Gelkis auf und sprecht dann mit Uthek der Weisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1383] = { id = 1383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichts als die Wahrheit", description = "Mir schwebt genau das richtige Serum vor. Es wird die Wahrheit genau so behandeln, wie die Wahrheit behandelt werden sollte.\n\nFür dieses Gebräu brauche ich mehrere Schattenpantherherzen aus dem Sumpf. Außerdem brauche ich den verzauberten Fungus des Morastlords, der dort haust. Ich bin sicher, jemand, der so tüchtig ist wie Ihr, {name}, kann ihn überreden, sich von einigen zu trennen.\n\nDie letzte Zutat für das Serum ist das Blut eines träumenden Welpen, wie jene, die außerhalb Itharius' Höhle in den Sümpfen leben.\n\nUnd jetzt fort mit Euch!", sourceObjective = "Apotheker Faustin im Bettlerschlupfwinkel braucht 5 Schattenpantherherzen, Morastlordfungus und etwas Blut eines grünen Welpen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1384] = { id = 1384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überfall auf die Kolkar", description = "Die Kolkarzentauren glauben, ihre Magie sei stark. Die wissen nicht, was Magie ist! Nie und nimmer würden die richtige Magie überhaupt erkennen!\n\nIhr werdet ihnen zeigen, dass ihre Magie schwach ist. Geht zu den Kolkar im Nordosten und tötet sie. Nehmt ihre Glücksbringer. Bringt mir die Glücksbringer und ich werfe sie ins Feuer und lache!", sourceObjective = "Wahrt Euren Ruf bei den Gelkis und bringt 10 kunstlose Glücksbringer zu Uthek der Weisen im Dorf der Gelkis in Desolace.", sourceObjectiveStatus = "unverified-source-field" }
quests[1385] = { id = 1385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brutale Politik", description = "Desolace ist ein Land im Krieg. Die Zentauren führen Krieg untereinander und wir glauben, der Sieger wird ausrücken und unsere Festungen bedrohen. Das können wir nicht dulden.\n\nWir müssen lernen, wie man die Zentauren schlägt, und dazu... müssen wir uns mit einem der Klans verbünden. Die Zentauren der Magram führen Krieg mit den Gelkis. Wenn Ihr gegen die Gelkis kämpft, dann erwägen die Magram vielleicht eine Allianz.\n\nErringt die Gunst der Magram und sprecht dann mit Warug im Dorf Magram im Südosten von Desolace.", sourceObjective = "Baut Euch einen freundlichen Ruf bei den Magram auf und sprecht dann mit Warug.", sourceObjectiveStatus = "unverified-source-field" }
quests[1386] = { id = 1386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Kolkar", description = "Die Kolkar halten sich für stark, aber wir lachen über sie! Wir lachen und wir töten sie! Tötet auch Ihr sie. Zeigt mir, dass Ihr Kolkar genauso wie wir töten könnt. Geht nach Norden und tötet sie alle!", sourceObjective = "Haltet Euren Ruf bei den Magram aufrecht. Tötet 12 Zentauren der Kolkar, 12 Späher der Kolkar sowie 6 Raufer der Kolkar und kehrt dann zu Warug ins Magramdorf in Desolace zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1387] = { id = 1387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zentaurenkopfgeld", description = "Viele Klans bilden das Volk der Zentauren. Jeder hat seinen Anführer und eine Agenda, aber alle Klans haben eines gemeinsam: Grausamkeit.\n\nWenn wir je Frieden finden wollen, müssen die Zentauren entfernt werden. Und ich übertrage Euch die Aufgabe, genau das zu tun.\n\nWenn Ihr durch Desolace zieht, jagt Zentauren und sammelt ihre Ohren. Bringt mir viele, viele Ohren.\n\nMacht das im Dienst der Allianz, {name}, und wir sind dem Ende des Krieges einen Schritt näher.", sourceObjective = "Bringt 15 Zentaurenohren zu Korporal Melkins bei der Nijelspitze in Desolace.", sourceObjectiveStatus = "unverified-source-field" }
quests[1388] = { id = 1388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichts als die Wahrheit", description = "Alles läuft genau nach Plan, {name}. Ich möchte, dass Ihr dieses Wahrheitsserum dem Todespirscher Zraedus gebt. Er wird Euch zeigen, wie man es richtig... anwendet.\n\nHa-ha!", sourceObjective = "Gebt Faustins Wahrheitsserum dem Todespirscher Zraedus im Bettlerschlupfwinkel.", sourceObjectiveStatus = "unverified-source-field" }
quests[1389] = { id = 1389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draenethystkristalle", description = "Die Verirrten, die in der Zuflucht der Verirrten leben, sehen aus wie wir, aber sie sind Monster... die üblen Unbilden auf unserem Treck nach Azeroth haben sie wahnsinnig gemacht. Einst waren sie unsere Brüder, doch nun leben sie in der Zuflucht der Verirrten im Osten und fangen oder töten alle, die sich in die Nähe wagen.\n\nUnd sie haben uns etwas Heiliges gestohlen - Draenethystkristalle.\n\nUns fehlt die Kraft, um die Zuflucht der Verirrten zu betreten und unseren gestohlenen Draenethyst von ihren Hütten und Lagerfeuern zu holen, aber ohne diese Kristalle... könnten auch wir vom rechten Weg abkommen.", sourceObjective = "Bringt 6 Draenethystkristalle zu Magtoor im Sicheren Hafen in den Sümpfen des Elends.", sourceObjectiveStatus = "unverified-source-field" }
quests[1391] = { id = 1391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichts als die Wahrheit", description = "Wir müssen mit einer gewissen Diskretion vorgehen. Immerhin werdet Ihr nicht da reinspazieren und den Narren überzeugen, Faustins Gebräu zu trinken, richtig?\n\nAber wenn es eines gibt, zu dem die Menschen nicht nein sagen können, dann ist es Fusel. Ich nehme Faustins Serum und mische es in dieses Bier. Der arme Kerl wird garantiert keine Hemmungen haben, wenn es darum geht, ein Gebräu zu kippen.\n\nGeht hastig nach Steinard in den Sümpfen des Elends, {name}. Und schweigt schön stille über unsere kleine Mission...", sourceObjective = "Bringt Zraedus' Bräu zu Spitzel Marksen in Steinard.", sourceObjectiveStatus = "unverified-source-field" }
quests[1392] = { id = 1392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noboru der Knüppel", description = "Noboru plagt die Draenei des Sicheren Hafens seit Monaten; sein Knüppel ist ein Symbol der Brutalität, die sie sich von den Verirrten gefallen lassen mussten.", sourceObjective = "Bringt Noborus Knüppel zum Anführer des Sicheren Hafens in den Sümpfen des Elends.", sourceObjectiveStatus = "unverified-source-field" }
quests[1393] = { id = 1393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Galens Flucht", description = "Bitte helft! Diese Kreaturen werden mich fressen!\n\nHelft mir hier raus und ich gebe Euch einen großen Schatz! Er ist in meinem Lager im Sumpf im Norden von Steinard, aber in einer Geldkassette eingeschlossen, die man mit einem Trick öffnet, den nur ich beherrsche.\n\nWenn Ihr mir zur Flucht verhelft, zeige ich ihn Euch.", sourceObjective = "Eskortiert Galen, bis er außer Gefahr ist, sucht dann sein Lager in den Sümpfen des Elends und öffnet seine Geldkassette.", sourceObjectiveStatus = "unverified-source-field" }
quests[1394] = { id = 1394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Letzte Überfahrt", description = "Ihr habt Eure Sache gut gemacht, {name}. Ihr habt meinen Test und die Tests vor meinem bestanden. Kehrt zu Dorn in Tausend Nadeln zurück. Er wird die Veränderung in Euch spüren und sehen, dass Euer Verstand, Körper und Geist stark genug sind, dass Ihr für Eure Bemühungen belohnt werden solltet.\n\nBleibt dem Gleichgewicht treu, das Ihr während all dieser Prüfungen gezeigt habt, {name}. Wenn Ihr das tut, wird Dorn Euch irgendwann noch einmal prüfen.", sourceObjective = "Sprecht mit Dorn Ebenenpirscher in Tausend Nadeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[1395] = { id = 1395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte für Nethergarde", description = "Diese Kiste mit Kraftsteinen muss in die Burg Nethergarde in den Verwüsteten Landen. Sie werden ihre Macht nicht lange halten, daher können wir sie nicht mit der nächsten Karawane aufgeben.\n\nIhr müsst sie nehmen, und zwar schnell.\n\nBringt sie zu Rüstmeister Lungertz in der Burg Nethergarde. Um die Burg zu erreichen, müsst Ihr nach Osten über den Gebirgspass der Totenwinde, dann nach Osten durch die Sümpfe des Elends und dann nach Süden durch die Verwüsteten Lande.\n\nSeid vorsichtig, {name}. Ihr müsst durch gefährliche Länder und dürft doch nicht verzagen.", sourceObjective = "Bringt die Kiste mit den Kraftsteinen zu Rüstmeister Lungertz, bevor die Kraft verbraucht ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[1396] = { id = 1396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lauernde Tierwelt", description = "Meine Karawane sollte zur östlichen Küste ziehen, aber wir erreichten unser Ziel nicht. Verirrte haben uns angegriffen, die Wachen getötet und die Vorräte verstreut.\n\nIch allein habe ihren Angriff überlebt. Ich habe geschworen, die verbliebenen Vorräte zu schützen, aber wilde Kreaturen schleichen in der Nähe herum. Bitte helft mir, mein Lager gegen diese Bestien zu verteidigen!", sourceObjective = "Tötet 8 junge Sägezahnkrokilisken, 10 Trauerspinner sowie 10 Sumpfjaguare und kehrt dann zu Behüter Biggs in den Sümpfen des Elends zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1398] = { id = 1398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treibholz", description = "Ich stehe tief in Eurer Schuld, {name}. Ein ehrenhaftes Herz schlägt in Eurer Brust. Und jetzt habe ich eine andere Aufgabe, für die ich demütig um Eure Mithilfe bitte.\n\nWenn ich Nethergarde erreichen soll, dann muss ich diesen Wagen reparieren. Und dafür...brauche ich Holz. Starkes, trockenes Holz - nicht das schimmelige, krumme Holz der Sumpfbäume.\n\n{name}, geht nach Osten zur Küste und sucht nach in der Sonne getrocknetem Treibholz. Bringt es mir.", sourceObjective = "Bringt 8 Stücke sonnengetrocknetes Treibholz zu Behüter Biggs in den Sümpfen des Elends.", sourceObjectiveStatus = "unverified-source-field" }
quests[1418] = { id = 1418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neeka Blutnarbe", description = "Das Ödland ist unwirtlich und liegt nahe am Land des Loch Modan, das von der Allianz beherrscht wird, daher wird die Kommunikation zwischen Steinard und den Ödland-Außenposten von Kargath oft unterbrochen.\n\nBeweist Euch, {name}. Reist ins Ödland und sprecht mit Neeka Blutnarbe, der obersten Späherin des Kargath-Außenpostens. Sprecht mit ihr und bringt mir ihren Bericht.", sourceObjective = "Sprecht mit Neeka Blutnarbe.", sourceObjectiveStatus = "unverified-source-field" }
quests[1419] = { id = 1419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kojoten-Diebe", description = "Habt Ihr viele Tage im Ödland verbracht, {class}? Habt Ihr sein Herz gespürt? Habt Ihr den Bestien getrotzt, die durch die staubigen Ebenen schleichen? Dann wird es aber höchste Zeit.\n\nKlippenkojoten sind zähe Burschen. Zäh und tollkühn genug, dass sie sich nach Kargath schleichen und unsere Essensvorräte stehlen. Helft mit, den Außenposten von diesen Dieben zu befreien!\n\nJagt Klippenkojoten, {name}. Jagt sie und bringt mir ihre Kieferknochen. Bringt mir genügend und ich glaube Euch vielleicht, wenn Ihr sagt, dass Ihr das Ödland kennt.", sourceObjective = "Bringt 30 Kojotenkieferknochen zu Neeka Blutnarbe in Kargath.", sourceObjectiveStatus = "unverified-source-field" }
quests[1420] = { id = 1420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht für Helgrum", description = "Ich schrieb einen neuen Bericht für Helgrum in Steinard. Bringt ihn zu ihm.\n\nUnd wenn Ihr Euch als Kundschafter betrachtet, kommt nicht vom Weg ab. Oder fallt einem Feind in die Hände.", sourceObjective = "Bringt Neekas Bericht zu Helgrum dem Hurtigen in Steinard.", sourceObjectiveStatus = "unverified-source-field" }
quests[1421] = { id = 1421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verlorene Karawane", description = "Ich wurde während des Angriffs der Verirrten betäubt, aber bevor mir schwarz vor Augen wurde, sah ich einen unserer Wagen, der zur Zuflucht der Verirrten gezerrt wurde, das Dorf der Verirrten im Norden.\n\nEine Karawanentruhe mit wertvollen Reagenzien war in diesem Wagen, Reagenzien, die unabdingbar für die Studien der Hexer der Burg Nethergarde sind. Sucht die Truhe und holt diese Reagenzien, {name}. Holt sie und bringt sie mir.", sourceObjective = "Sucht die Karawanentruhe in der Zuflucht der Verirrten, beschafft Euch die Reagenzien der Hexer und bringt sie zu Behüter Biggs.", sourceObjectiveStatus = "unverified-source-field" }
quests[1422] = { id = 1422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefahr aus dem Meer", description = "Warum unterhaltet Ihr Euch nicht mit Katar, während ich an Eurer Waffe arbeite? Er erwähnte, dass er Hilfe bei Patrouillen am Strand braucht, und mir wäre es lieber, Ihr würdet Euren Geist und Eure Waffen trainieren, anstatt Euch mit den anderen Tunichtguten in diesem Lager zu betrinken.", sourceObjective = "Sprecht mit Katar in den Sümpfen des Elends.", sourceObjectiveStatus = "unverified-source-field" }
quests[1423] = { id = 1423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verlorenen Vorräte", description = "Dieses Fass ist klein, aber stabil. Seine Ritzen sind mit einem gelben, duftenden Wachs versiegelt. Auf der Unterseite des Fasses stehen die Worte:\n\nRÜSTMEISTER LUNGERTZ\n\nBURG NETHERGARDE", sourceObjective = "Bringt die verlorenen Vorräte zu Rüstmeister Lungertz.", sourceObjectiveStatus = "unverified-source-field" }
quests[1424] = { id = 1424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tränenteich", description = "Der Kriegshäuptling schickt uns, die seltsamen Vorkommnisse im Tempel von Atal'Hakkar zu untersuchen.\n\nDie Trolle des Stammes der Atal'ai sind ein Stamm dunkler Zauberkundiger, die dafür bekannt sind, verbotene Magie auszuüben. Ihr könnt Euch vorstellen, wie erstaunt wir waren, als wir hier eintrafen und feststellten, dass der Tempel versunken war.\n\nDie grünen Großdrachen hüten nun die Stelle und spielen sich als Beschützer von Azeroth auf.\n\nWir müssen herausfinden, was geschehen ist. Forscht rund um den Tränenteich und sammelt Artefakte der Atal'ai. Damit kann ich dieses Rätsel lösen.", sourceObjective = "Fel'Zerul in Steinard möchte, dass Ihr 5 Artefakte der Atal'ai sammelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1425] = { id = 1425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überbringen der Lieferung", description = "Während ich diesen Wagen repariere, {name}, habe ich eine letzte Aufgabe für Euch.\n\nIch habe die wichtigsten Vorräte eingepackt, die ich vor den Angriffen der Oger retten konnte. Bringt sie zur Burg Nethergarde. Die Burg schmiegt sich an die nördlichen Hügel der Verwüsteten Lande und wacht über das Dunkle Portal.\n\nFolgt der Straße nach Osten, um Nethergarde zu erreichen. Geht an der Gabelung nach Süden in die Verwüsteten Lande und bei der nächsten Gabelung nach links. Folgt der Straße, {name}, und seid wachsam.", sourceObjective = "Bringt die Ladung für Nethergarde zu Rüstmeister Lungertz in der Burg Nethergarde.", sourceObjectiveStatus = "unverified-source-field" }
quests[1426] = { id = 1426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefahr aus dem Meer", description = "Ich mag weder das Meer noch die Kreaturen, die ich aus seiner Tiefe kommen sah. Es ist eine mächtige, aber blinde Herrin; launisch und brutal. Es wäre mir ein Vergnügen, die Fischmenschen zu Hunderten zu töten, wenn es in meiner Macht stünde. Eine kleine Freude ist es mir wenigstens, sie durch die Hände all derer sterben zu sehen, die den Willen der Horde erfüllen.\n\nUnd damit sind wir bei Euch, {class}. Wie viele könnt Ihr besiegen? Würdet Ihr Euch mit dem Mächtigsten ihrer Art messen?", sourceObjective = "Tötet 10 Marschenmurlocs, 10 Marschentintenspucker und 10 Marschenfleischfresser und kehrt dann zu Katar in den Sümpfen des Elends zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1427] = { id = 1427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefahr aus dem Meer", description = "Sprecht wieder mit Tok'Kar, bevor Ihr Euch ausruht. Während Ihr fort wart, hat er, glaube ich, ein paar Waffen vollendet. Für Eure Hilfe würde er Euch eine davon anbieten. Ihr tätet gut daran, ihre Kraft an den Fischmenschen zu erproben, wenn Ihr bereit seid...aber nur, um mich weiterhin zu erfreuen.", sourceObjective = "Sprecht mit Tok'Kar in den Sümpfen des Elends.", sourceObjectiveStatus = "unverified-source-field" }
